/** Skaner dywidendowy — wyszukiwarka spółek i funduszy pod kątem wypłat.
 *
 *  Filtry są ułożone pod pytania, które inwestor dywidendowy zadaje naprawdę,
 *  a nie pod pola, jakie akurat mamy w danych. Stąd „bez obcięcia w historii"
 *  i „minimalna seria podwyżek" na wierzchu, a wskaźnik wypłaty i ocena
 *  w rozwijanym panelu — pierwsze dwa odsiewają najwięcej, reszta doprecyzowuje.
 *
 *  Lista jest darmowa (po zalogowaniu) i to jest celowe: zablokowana nie
 *  pozwoliłaby ocenić, czy narzędzie jest cokolwiek warte.
 */
import React, { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator, Pressable, ScrollView, StyleSheet, Text, TextInput, View,
} from "react-native";
import { DywFiltry, DywMeta, DywRow, screenDyw } from "../../../api";
import { C, T } from "../../../theme";
import { Card, Segmented } from "../../../ui";
import {
  Akapit, dataPl, Kafel, OdznakaOceny, Pigulka, proc, useSzerokoscUkladu,
  Wyjasnienie, zaIleDni, Znak, ZnacznikRynku,
} from "./shared";

const STRONA = 30;

export default function Skaner({ meta, naAktywo, wybrane, przelaczWybor }: {
  meta: DywMeta;
  naAktywo: (symbol: string) => void;
  wybrane: string[];
  przelaczWybor: (symbol: string) => void;
}) {
  const { szeroko } = useSzerokoscUkladu();
  const [f, setF] = useState<DywFiltry>({ sort: "stopa" });
  const [szukaj, setSzukaj] = useState("");
  const [rozwiniete, setRozwiniete] = useState(false);
  const [rows, setRows] = useState<DywRow[]>([]);
  const [total, setTotal] = useState(0);
  const [laduje, setLaduje] = useState(true);
  const [blad, setBlad] = useState("");

  const pobierz = useCallback(async (offset: number) => {
    setLaduje(true);
    setBlad("");
    try {
      const r = await screenDyw({ ...f, szukaj, limit: STRONA, offset });
      setTotal(r.total);
      setRows((stare) => (offset ? [...stare, ...r.rows] : r.rows));
    } catch (e: any) {
      setBlad(e?.message || "Nie udało się pobrać listy");
    } finally {
      setLaduje(false);
    }
  }, [f, szukaj]);

  // Zwłoka przy wpisywaniu — bez niej każda litera to osobne żądanie do serwera.
  useEffect(() => {
    const t = setTimeout(() => pobierz(0), szukaj ? 350 : 0);
    return () => clearTimeout(t);
  }, [pobierz, szukaj]);

  const ustaw = (k: keyof DywFiltry, v: any) =>
    setF((s) => ({ ...s, [k]: s[k] === v ? undefined : v }));

  const aktywnych = Object.entries(f)
    .filter(([k, v]) => k !== "sort" && v !== undefined && v !== "").length;

  return (
    <View style={{ gap: 12 }}>
      <TextInput
        value={szukaj}
        onChangeText={setSzukaj}
        placeholder="Szukaj spółki albo tickera…"
        placeholderTextColor={C.dim}
        style={st.szukaj}
        autoCorrect={false}
      />

      <ScrollView horizontal showsHorizontalScrollIndicator={false}
                  contentContainerStyle={st.rzad}>
        {meta.rynki.map((r) => (
          <Pigulka key={r.id || "all"} tekst={r.nazwa}
                   aktywna={(f.rynek || "") === r.id}
                   onPress={() => setF((s) => ({ ...s, rynek: r.id || undefined }))} />
        ))}
        <View style={st.kreska} />
        <Pigulka tekst="Tylko rosnące" aktywna={f.rosnace === "1"}
                 onPress={() => ustaw("rosnace", "1")} />
        <Pigulka tekst="Bez obcięcia" aktywna={f.bez_obcinania === "1"}
                 onPress={() => ustaw("bez_obcinania", "1")} />
        <Pigulka tekst="Stopa 4%+" aktywna={String(f.min_stopa) === "4"}
                 onPress={() => ustaw("min_stopa", 4)} />
        <Pigulka tekst="Co kwartał" aktywna={f.czestotliwosc === "4"}
                 onPress={() => ustaw("czestotliwosc", "4")} />
        <Pigulka tekst="Co miesiąc" aktywna={f.czestotliwosc === "12"}
                 onPress={() => ustaw("czestotliwosc", "12")} />
      </ScrollView>

      <Pressable onPress={() => setRozwiniete((v) => !v)} style={st.wiecejBtn}>
        <Text style={st.wiecejTxt}>
          {rozwiniete ? "▾ Mniej filtrów" : "▸ Więcej filtrów"}
          {aktywnych > 0 ? `  ·  ${aktywnych} aktywnych` : ""}
        </Text>
      </Pressable>

      {rozwiniete && (
        <Card>
          <Text style={st.grupa}>Wskaźnik wypłaty — ile zysku spółka oddaje</Text>
          <ScrollView horizontal showsHorizontalScrollIndicator={false}
                      contentContainerStyle={st.rzad}>
            {[40, 60, 80, 100].map((v) => (
              <Pigulka key={v} tekst={`do ${v}%`} aktywna={String(f.max_wyplata) === String(v)}
                       onPress={() => ustaw("max_wyplata", v)} />
            ))}
          </ScrollView>

          <Text style={st.grupa}>Minimalna seria podwyżek</Text>
          <ScrollView horizontal showsHorizontalScrollIndicator={false}
                      contentContainerStyle={st.rzad}>
            {[1, 3, 5, 10].map((v) => (
              <Pigulka key={v} tekst={`${v}+ lat`} aktywna={String(f.min_seria) === String(v)}
                       onPress={() => ustaw("min_seria", v)} />
            ))}
          </ScrollView>

          <Text style={st.grupa}>Minimalna ocena bezpieczeństwa</Text>
          <ScrollView horizontal showsHorizontalScrollIndicator={false}
                      contentContainerStyle={st.rzad}>
            {[40, 60, 80].map((v) => (
              <Pigulka key={v} tekst={`${v}+`} aktywna={String(f.min_ocena) === String(v)}
                       onPress={() => ustaw("min_ocena", v)} />
            ))}
          </ScrollView>

          {meta.sektory.length > 0 && (
            <>
              <Text style={st.grupa}>Branża</Text>
              <ScrollView horizontal showsHorizontalScrollIndicator={false}
                          contentContainerStyle={st.rzad}>
                {meta.sektory.map((sek) => (
                  <Pigulka key={sek} tekst={sek} aktywna={f.sektor === sek}
                           onPress={() => ustaw("sektor", sek)} />
                ))}
              </ScrollView>
            </>
          )}

          <Pressable onPress={() => { setF({ sort: f.sort }); setSzukaj(""); }}
                     style={st.wyczysc}>
            <Text style={st.wyczyscTxt}>Wyczyść filtry</Text>
          </Pressable>
        </Card>
      )}

      <Segmented
        options={meta.sortowania.slice(0, 4).map((o) => ({
          id: o.id, label: szeroko ? o.nazwa : (o.krotka || o.nazwa),
        }))}
        value={f.sort || "stopa"}
        onChange={(id) => setF((s) => ({ ...s, sort: id }))}
      />

      <Text style={st.licznik}>
        {laduje && rows.length === 0 ? "Szukam…" : `${total} ${odmiana(total)}`}
        {meta.gotowe < meta.w_katalogu
          ? `  ·  dane gotowe dla ${meta.gotowe} z ${meta.w_katalogu} spółek`
          : ""}
      </Text>

      {!!blad && <Text style={st.blad}>{blad}</Text>}

      {/* Na monitorze dwie kolumny: pojedynczy wiersz rozciągnięty na 1180 px
          to nazwa przy jednej krawędzi i stopa przy drugiej, z pustką pomiędzy. */}
      <View style={szeroko ? st.siatka : undefined}>
        {rows.map((w) => (
          <View key={w.symbol} style={szeroko ? st.komorka : undefined}>
            <Wiersz w={w}
                    zaznaczony={wybrane.includes(w.symbol)}
                    naKlik={() => naAktywo(w.symbol)}
                    naZaznacz={() => przelaczWybor(w.symbol)} />
          </View>
        ))}
      </View>

      {laduje && rows.length > 0 && <ActivityIndicator color={C.green} />}

      {rows.length < total && !laduje && (
        <Pressable onPress={() => pobierz(rows.length)} style={st.wiecejBtn}>
          <Text style={st.wiecejTxt}>Pokaż kolejne {Math.min(STRONA, total - rows.length)}</Text>
        </Pressable>
      )}

      {!laduje && rows.length === 0 && !blad && (
        <Card>
          <Text style={st.pustoTytul}>Nic nie pasuje do tych filtrów</Text>
          <Akapit>
            Spróbuj poluzować najostrzejszy z nich. Najczęściej jest to wskaźnik
            wypłaty albo minimalna seria podwyżek — spółek, które podnoszą
            dywidendę dziesięć lat z rzędu, jest na całym świecie garstka,
            a na GPW pojedyncze.
          </Akapit>
        </Card>
      )}

      <Card>
        <Wyjasnienie tytul="Dlaczego najwyższa stopa nie znaczy najlepsza spółka">
          <Akapit>
            Stopa dywidendy to dywidenda podzielona przez kurs. Rośnie więc nie
            tylko wtedy, gdy spółka podnosi wypłatę, ale też wtedy, gdy jej kurs
            spada — a spadający kurs zwykle ma powód. Dlatego na szczycie listy
            posortowanej po stopie prawie zawsze siedzą spółki w kłopotach albo
            takie, które raz wypłaciły coś jednorazowego.
          </Akapit>
          <Akapit>
            Drugą liczbą, na którą warto patrzeć od razu, jest wskaźnik wypłaty:
            jaką część zysku spółka oddaje. Powyżej 100% wypłaciła więcej, niż
            zarobiła — z oszczędności albo z długu, i taka dywidenda rzadko
            powtarza się w kolejnym roku.
          </Akapit>
        </Wyjasnienie>
        <Wyjasnienie tytul="Co oznacza ocena od 0 do 100">
          <Akapit>
            To skrót z czterech sprawdzalnych faktów: jaką część zysku spółka
            oddaje, ile lat z rzędu podnosiła wypłatę, czy kiedykolwiek ją
            obcięła i czy stopa nie jest podejrzanie wysoka. Opisuje wyłącznie
            przeszłość — nie jest prognozą i nie ma pojęcia, co spółka zrobi
            w przyszłym roku.
          </Akapit>
          <Akapit>
            Spółka bez oceny to taka, dla której mamy mniej niż trzy zamknięte
            lata historii wypłat. Wolimy napisać „nie wiem" niż wystawić notę
            na podstawie jednej wypłaty.
          </Akapit>
        </Wyjasnienie>
      </Card>
    </View>
  );
}

function odmiana(n: number): string {
  if (n === 1) return "spółka";
  const d = n % 10;
  const s = n % 100;
  if (d >= 2 && d <= 4 && !(s >= 12 && s <= 14)) return "spółki";
  return "spółek";
}

function Wiersz({ w, zaznaczony, naKlik, naZaznacz }: {
  w: DywRow; zaznaczony: boolean; naKlik: () => void; naZaznacz: () => void;
}) {
  return (
    <Pressable onPress={naKlik} style={[st.wiersz, zaznaczony && st.wierszZazn]}>
      <Znak symbol={w.symbol} nazwa={w.nazwa} rozmiar={36} />
      <View style={{ flex: 1, gap: 4 }}>
        <View style={st.linia}>
          <Text style={st.nazwa} numberOfLines={1}>{w.nazwa}</Text>
          <ZnacznikRynku rynek={w.rynek} />
        </View>
        <Text style={st.pod} numberOfLines={1}>
          {w.ticker}
          {w.sektor ? ` · ${w.sektor}` : ""}
          {` · ${w.czestotliwosc_pl}`}
        </Text>
        <View style={st.znaczniki}>
          {w.seria_wzrostow > 0 && (
            <Text style={[st.znacznik, { color: C.green, borderColor: C.green + "55" }]}>
              ↑ {w.seria_wzrostow} {w.seria_wzrostow === 1 ? "rok" : "lat"} podwyżek
            </Text>
          )}
          {w.obcinala && (
            <Text style={[st.znacznik, { color: C.amber, borderColor: C.amber + "55" }]}>
              obcinała
            </Text>
          )}
          {w.ex_przyszla && w.dni_do_ex !== null && w.dni_do_ex <= 45 && (
            <Text style={[st.znacznik, { color: C.accent, borderColor: C.accent + "55" }]}>
              bez dywidendy {zaIleDni(w.dni_do_ex)}
            </Text>
          )}
        </View>
      </View>

      <View style={st.prawa}>
        <Text style={st.stopa}>{proc(w.stopa)}</Text>
        <Text style={st.stopaNota}>
          {w.wyplata !== null ? `wypłata ${Math.round(w.wyplata)}%` : "wypłata: brak danych"}
        </Text>
        <View style={{ flexDirection: "row", alignItems: "center", gap: 6, marginTop: 4 }}>
          <OdznakaOceny ocena={w.ocena} poziom={w.poziom} male />
          <Pressable onPress={naZaznacz} hitSlop={8}
                     style={[st.check, zaznaczony && { backgroundColor: C.green, borderColor: C.green }]}>
            <Text style={[st.checkTxt, zaznaczony && { color: "#04120b" }]}>
              {zaznaczony ? "•" : "+"}
            </Text>
          </Pressable>
        </View>
      </View>
    </Pressable>
  );
}

const st = StyleSheet.create({
  szukaj: {
    backgroundColor: C.card, borderWidth: 1, borderColor: C.border, borderRadius: 12,
    paddingHorizontal: 13, paddingVertical: 11, color: C.text, ...T.body,
  },
  rzad: { gap: 7, paddingRight: 8, alignItems: "center" },
  kreska: { width: 1, height: 20, backgroundColor: C.border2, marginHorizontal: 3 },
  grupa: { ...T.micro, color: C.dim, textTransform: "uppercase",
           letterSpacing: 0.5, marginTop: 12, marginBottom: 7 },
  wyczysc: { marginTop: 14, alignSelf: "flex-start" },
  wyczyscTxt: { ...T.small, color: C.red, fontWeight: "600" },
  wiecejBtn: { paddingVertical: 9, alignItems: "center" },
  wiecejTxt: { ...T.small, color: C.green, fontWeight: "700" },
  licznik: { ...T.micro, color: C.dim },
  blad: { ...T.small, color: C.red },

  wiersz: {
    flexDirection: "row", gap: 12, alignItems: "center",
    backgroundColor: C.card, borderRadius: 12, borderWidth: 1,
    borderColor: C.border, padding: 12,
  },
  wierszZazn: { borderColor: C.green, backgroundColor: C.greenDim },
  siatka: { flexDirection: "row", flexWrap: "wrap", gap: 10 },
  komorka: { flexGrow: 1, flexBasis: "48%", maxWidth: "50%" },
  linia: { flexDirection: "row", alignItems: "center", gap: 7 },
  nazwa: { ...T.body, color: C.text, fontWeight: "700", flexShrink: 1 },
  pod: { ...T.micro, color: C.dim },
  znaczniki: { flexDirection: "row", flexWrap: "wrap", gap: 5, marginTop: 2 },
  znacznik: {
    ...T.micro, fontSize: 10, borderWidth: 1, borderRadius: 6,
    paddingHorizontal: 5, paddingVertical: 2,
  },
  prawa: { alignItems: "flex-end" },
  stopa: { ...T.body, color: C.green, fontSize: 21, fontWeight: "800" },
  stopaNota: { ...T.micro, color: C.dim, fontSize: 10 },
  check: {
    width: 26, height: 26, borderRadius: 8, borderWidth: 1, borderColor: C.border2,
    alignItems: "center", justifyContent: "center",
  },
  checkTxt: { ...T.body, color: C.muted, fontWeight: "800", lineHeight: 18 },
  pustoTytul: { ...T.body, color: C.text, fontWeight: "700", marginBottom: 6 },
});
