/** Znak marki „Portevo" — koło sterowe w miejscu litery O, ze wzrostową strzałką w środku.
 *
 *  Rysowany wektorowo, a nie wklejony jako obrazek: jest ostry w każdym rozmiarze,
 *  nie wnosi białego tła na ciemny motyw i bierze kolory z palety aplikacji.
 */
import React from "react";
import { Image, ImageStyle, StyleSheet, Text, View, ViewStyle } from "react-native";
import Svg, { Circle, G, Path, Line } from "react-native-svg";
import { C } from "../theme";

/** Sama łódka z wykresem — bez napisu, bo napis rysujemy wektorowo (patrz `Brand`).
 *  Dzięki temu zmiana nazwy marki nie wymaga przerabiania pliku graficznego,
 *  a słowo jest ostre w każdym rozmiarze i bierze kolory z motywu. */
const MARK = require("../../assets/logo-portevo-mark.png");
const MARK_RATIO = 372 / 118;

export function BrandMark({
  width = 160, style, opacity = 1,
}: { width?: number; style?: ImageStyle; opacity?: number }) {
  return (
    <Image
      source={MARK}
      accessibilityLabel="Portevo"
      style={[{ width, height: width / MARK_RATIO, opacity }, style]}
      resizeMode="contain"
    />
  );
}

/** Pełne logo: łódka nad napisem — tak, jak wyglądał scalony plik PNG. */
export function BrandLogo({
  width = 160, style, opacity = 1,
}: { width?: number; style?: ViewStyle; opacity?: number }) {
  return (
    <View style={[{ width, opacity, alignItems: "center" }, style]}>
      <BrandMark width={width} />
      {/* ujemny odstęp zjada światło interlinii nad literami — bez tego napis
          odkleja się od łódki mocniej niż na scalonym pliku */}
      <Brand size={width * 0.2} style={{ marginTop: -width * 0.03 }} />
    </View>
  );
}

/** Stopka sekcji — znak na końcu listy, żeby ekran nie kończył się w powietrzu. */
export function BrandFooter({ note, width = 108 }: { note?: string; width?: number }) {
  return (
    <View style={s.footer}>
      <BrandLogo width={width} opacity={0.42} />
      {!!note && <Text style={s.footerTxt}>{note}</Text>}
    </View>
  );
}

const RING = 34;          // promień obręczy w układzie 100×100
const HANDLE_OUT = 47;    // dokąd sięgają rękojeści koła
const ANGLES = [0, 45, 90, 135, 180, 225, 270, 315];

const pt = (deg: number, r: number): [number, number] => [
  50 + r * Math.cos((deg * Math.PI) / 180),
  50 + r * Math.sin((deg * Math.PI) / 180),
];

/** Samo koło sterowe — do miejsc, gdzie na pełny napis nie ma miejsca. */
export function Wheel({
  size, blue = C.brandBlue, orange = C.brandOrange,
}: { size: number; blue?: string; orange?: string }) {
  return (
    <Svg width={size} height={size} viewBox="0 0 100 100">
      <G>
        {ANGLES.map((a) => {
          const [x1, y1] = pt(a, RING);
          const [x2, y2] = pt(a, HANDLE_OUT);
          return (
            <Line key={`h${a}`} x1={x1} y1={y1} x2={x2} y2={y2}
                  stroke={blue} strokeWidth={7} strokeLinecap="round" />
          );
        })}
        <Circle cx={50} cy={50} r={RING} stroke={blue} strokeWidth={9} fill="none" />
        {/* szprychy tylko na skos — pionowe zlewałyby się ze strzałką */}
        {[45, 135, 225, 315].map((a) => {
          const [x1, y1] = pt(a, 11);
          const [x2, y2] = pt(a, RING);
          return (
            <Line key={`s${a}`} x1={x1} y1={y1} x2={x2} y2={y2}
                  stroke={blue} strokeWidth={5} strokeLinecap="round" opacity={0.7} />
          );
        })}
        <Path d="M28 68 L44 52 L55 61 L70 38" stroke={orange} strokeWidth={8}
              fill="none" strokeLinecap="round" strokeLinejoin="round" />
        <Path d="M79 27 L76 47 L60 36 Z" fill={orange} />
      </G>
    </Svg>
  );
}

/** Pełny znak: PORTEVO z kołem sterowym zamiast pierwszego O. `size` = wysokość liter. */
export default function Brand({
  size = 26, style, muted = false,
}: { size?: number; style?: ViewStyle; muted?: boolean }) {
  const blue = muted ? C.muted : C.brandBlue;
  const orange = muted ? C.dim : C.brandOrange;
  const letter = { fontSize: size, lineHeight: size * 1.16 };

  return (
    <View style={[s.row, style]} accessibilityRole="header" accessibilityLabel="Portevo">
      <Text style={[s.word, letter, { color: blue }]}>P</Text>
      {/* koło jest lekko szersze niż litera, więc podbieramy odstęp po obu stronach */}
      <View style={{ marginHorizontal: -size * 0.06, marginBottom: size * 0.05 }}>
        <Wheel size={size * 1.02} blue={blue} orange={orange} />
      </View>
      <Text style={[s.word, letter, { color: blue }]}>RT</Text>
      <Text style={[s.word, letter, { color: orange }]}>EVO</Text>
    </View>
  );
}

const s = StyleSheet.create({
  row: { flexDirection: "row", alignItems: "center" },
  word: { fontWeight: "900", fontStyle: "italic", letterSpacing: -0.5 },
  footer: { alignItems: "center", marginTop: 26, gap: 8, paddingHorizontal: 16 },
  footerTxt: { color: C.dim, fontSize: 11, textAlign: "center", lineHeight: 16 },
  legalDisclaimer: { color: C.dim, fontSize: 10.5, textAlign: "center", lineHeight: 15, opacity: 0.75, marginTop: 2 },
});
