/** Unikatowe identyfikatory definicji SVG (gradienty, maski, przycięcia).
 *
 *  W przeglądarce wszystkie wykresy leżą w JEDNYM dokumencie, a `url(#fill)` wskazuje
 *  na PIERWSZY element o tym identyfikatorze na całej stronie — nie na ten z własnego
 *  <svg>. Dwa wykresy z tym samym `id="fill"` to nie drobiazg kosmetyczny: wykres
 *  spółki brał gradient i obszar przycięcia z wykresu portfela pod spodem, więc
 *  wypełnienie miało obcy kolor, a wszystko poniżej wysokości tamtego wykresu było
 *  po prostu ucinane — linia notowań znikała całymi kawałkami.
 *
 *  Stąd licznik: każdy zamontowany wykres dostaje własny przedrostek i przestaje
 *  zależeć od tego, co jeszcze jest na stronie.
 */
import { useMemo } from "react";

let seq = 0;

export function useSvgId(prefix: string): string {
  return useMemo(() => `${prefix}${++seq}`, [prefix]);
}
