/** Drobne funkcje dat dla panelu live.
 *
 *  Osobny plik, bo `LivePanel` importuje zakładki, a zakładki potrzebują tych
 *  funkcji. Trzymanie ich w `LivePanel` robiło cykl importów: przy starcie
 *  modułu `todayISO` bywało jeszcze niezdefiniowane i cała aplikacja gasła
 *  na białym ekranie, bez błędu w konsoli.
 */

/** Dzisiejsza data w formacie YYYY-MM-DD (czas lokalny, nie UTC). */
export function todayISO(): string {
  const d = new Date();
  d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
  return d.toISOString().slice(0, 10);
}

/** Przesuwa datę o N dni, zostając w formacie YYYY-MM-DD. */
export function shiftDate(iso: string, days: number): string {
  const d = new Date(iso + "T12:00:00");
  d.setDate(d.getDate() + days);
  d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
  return d.toISOString().slice(0, 10);
}

/** „Dziś" / „Jutro" zamiast surowej daty — czytelniej na wąskim ekranie. */
export function dayLabel(iso: string): string {
  const t = todayISO();
  if (iso === t) return "Dziś";
  if (iso === shiftDate(t, 1)) return "Jutro";
  if (iso === shiftDate(t, -1)) return "Wczoraj";
  return new Date(iso + "T12:00:00").toLocaleDateString("pl-PL",
    { weekday: "short", day: "numeric", month: "short" });
}
