/** Kod QR na ekranie — cienka warstwa rysująca nad enkoderem z `../qr`.
 *
 *  Rysujemy po `react-native-svg`, które projekt już ma: zachowuje się
 *  identycznie w przeglądarce i na telefonie, w przeciwieństwie do `canvas`.
 *  Gdy tekst nie mieści się w obsługiwanych wersjach kodu, komponent zwraca
 *  `null` zamiast rysować śmieci — ekran obok i tak pokazuje adres słownie.
 */
import React, { useMemo } from "react";
import { View, ViewStyle } from "react-native";
import Svg, { Path, Rect } from "react-native-svg";
import { macierzQr } from "../qr";

/* ------------------------------------------------------------ komponent */

export default function QrCode({
  value, size = 168, color = "#0b0e14", background = "#ffffff", style,
}: {
  value: string;
  size?: number;
  /** kolor modułów — musi być CIEMNIEJSZY od tła, inaczej czytniki odpadają */
  color?: string;
  background?: string;
  style?: ViewStyle;
}) {
  const macierz = useMemo(() => macierzQr(value), [value]);
  if (!macierz) return null;

  const n = macierz.length;
  // Cicha strefa: norma wymaga czterech modułów marginesu. Bez niej czytnik
  // gubi krawędź kodu na kolorowym tle i po prostu go nie widzi.
  const pelne = n + 8;
  const krok = size / pelne;

  // Jedna ścieżka na cały kod zamiast tysiąca prostokątów — przy 45×45 modułach
  // to różnica między jednym węzłem a dwoma tysiącami.
  let d = "";
  for (let y = 0; y < n; y++) {
    for (let x = 0; x < n; x++) {
      if (!macierz[y][x]) continue;
      const px = (x + 4) * krok;
      const py = (y + 4) * krok;
      d += `M${px.toFixed(2)},${py.toFixed(2)}h${krok.toFixed(2)}v${krok.toFixed(2)}h-${krok.toFixed(2)}z`;
    }
  }

  return (
    <View style={style}>
      <Svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
        <Rect x={0} y={0} width={size} height={size} rx={size * 0.06} fill={background} />
        <Path d={d} fill={color} />
      </Svg>
    </View>
  );
}
