/** Co właściwie chcesz dodać — okno wyboru przed wgraniem czegokolwiek.
 *
 *  Do tej pory „Wgraj raport" znaczyło jedno: plik z XTB. Teraz do portfela
 *  wchodzą trzy różne rzeczy i nie da się ich obsłużyć jednym przyciskiem:
 *  raport od brokera, którego znamy, raport od brokera, którego nie znamy,
 *  oraz majątek, którego żaden broker nie zna.
 *
 *  Kafle brokerów, których jeszcze nie umiemy czytać, są wygaszone i mówią
 *  wprost dlaczego. To jest uczciwsze niż ukrycie ich z listy: ktoś, kto ma
 *  rachunek w mBanku, widzi, że o nim wiemy i że droga przez odczyt AI stoi
 *  otworem — zamiast szukać, czy aplikacja w ogóle go obsługuje.
 */
import React from "react";
import { Modal, Pressable, ScrollView, StyleSheet, Text, View } from "react-native";
import { C, T } from "../theme";
import Icon, { IconName } from "../ui/Icon";

export type Wybor = "xtb" | "ai" | "majatek" | "recznie" | "portfel";

type Broker = {
  id: string;
  nazwa: string;
  /** gotowy parser — kafel aktywny i wyróżniony */
  dziala?: boolean;
  /** czym się wyróżnia na liście */
  nota?: string;
};

/** Kolejność jak w świadomości polskiego inwestora: XTB, potem banki, potem
 *  platformy zagraniczne. Lista jest jawna także dla brokerów bez parsera —
 *  patrz komentarz na górze pliku. */
const BROKERZY: Broker[] = [
  { id: "xtb", nazwa: "XTB", dziala: true, nota: "Pełne wsparcie" },
  { id: "mbank", nazwa: "mBank eMakler" },
  { id: "bos", nazwa: "DM BOŚ" },
  { id: "pko", nazwa: "DM PKO BP" },
  { id: "pekao", nazwa: "DM Pekao" },
  { id: "santander", nazwa: "Santander BM" },
  { id: "ibkr", nazwa: "Interactive Brokers" },
  { id: "degiro", nazwa: "DEGIRO" },
  { id: "saxo", nazwa: "Saxo Bank" },
  { id: "trading212", nazwa: "Trading 212" },
  { id: "revolut", nazwa: "Revolut" },
  { id: "etoro", nazwa: "eToro" },
];

export default function ImportChooser({ widoczne, zamknij, wybierz, aiZostalo }: {
  widoczne: boolean;
  zamknij: () => void;
  wybierz: (co: Wybor) => void;
  /** ile odczytów AI zostało; null = bez limitu (premium), undefined = nie wiemy */
  aiZostalo?: number | null;
}) {
  const [krok, setKrok] = React.useState<"start" | "broker">("start");

  React.useEffect(() => { if (widoczne) setKrok("start"); }, [widoczne]);

  return (
    <Modal visible={widoczne} animationType="slide" transparent onRequestClose={zamknij}>
      <View style={s.tlo}>
        <View style={s.okno}>
          <View style={s.glowa}>
            {krok === "broker" && (
              <Pressable onPress={() => setKrok("start")} hitSlop={10}>
                <Text style={s.wstecz}>‹</Text>
              </Pressable>
            )}
            <View style={{ flex: 1 }}>
              <Text style={s.tytul}>
                {krok === "start" ? "Co chcesz dodać?" : "Z którego biura?"}
              </Text>
              <Text style={s.podtytul}>
                {krok === "start"
                  ? "Portfel maklerski i majątek liczą się osobno, a razem dają pełny obraz"
                  : "Wybierz swojego brokera albo odczytaj raport przez AI"}
              </Text>
            </View>
            <Pressable onPress={zamknij} hitSlop={10} style={s.x}>
              <Icon name="zamknij" size={15} color={C.muted} />
            </Pressable>
          </View>

          <ScrollView contentContainerStyle={s.tresc} showsVerticalScrollIndicator={false}>
            {krok === "start" ? (
              <>
                <Duzy
                  ikona="broker"
                  tytul="Raport od brokera"
                  opis="Plik z historią rachunku. Wczytamy transakcje, koszty i pozycje — nic nie trzeba przepisywać."
                  kolor={C.green}
                  onPress={() => setKrok("broker")}
                />
                <Duzy
                  ikona="nieruchomosc"
                  tytul="Majątek"
                  opis="Mieszkanie, działka, złoto, obligacje skarbowe. Wpisujesz raz, a wartość liczy się razem z portfelem."
                  kolor={C.gold}
                  onPress={() => wybierz("majatek")}
                />
                {/* Trzecie wejście, mniejsze od dwóch powyżej, bo portfel sam
                    w sobie nie jest treścią — jest szufladą na treść. Musi tu
                    jednak być: sekcja „Twój majątek" w Przeglądzie pokazuje się
                    dopiero przy dwóch grupach, więc pierwszy portfel nie miałby
                    skąd powstać. */}
                <Duzy
                  ikona="teczka"
                  tytul="Nowy portfel"
                  opis={'Osobna grupa na rachunki i majątek — „Emerytura", „Spekulacja". '
                        + 'Wartości liczą się wtedy także osobno.'}
                  kolor={C.accent}
                  onPress={() => wybierz("portfel")}
                />
              </>
            ) : (
              <>
                <View style={s.siatka}>
                  {BROKERZY.map((b) => (
                    <Kafel key={b.id} broker={b}
                           onPress={() => b.dziala ? wybierz("xtb") : setKrok("broker")} />
                  ))}
                </View>

                <View style={s.kreska} />

                <Duzy
                  ikona="ai"
                  tytul="Odczytaj raport przez AI"
                  opis={
                    "Twojego brokera nie ma na liście albo plik wygląda dziwnie? "
                    + "Model przeczyta go i wypisze pozycje, a Ty je zatwierdzisz przed dodaniem."
                  }
                  kolor={C.violet}
                  odznaka={
                    aiZostalo === null ? "BEZ LIMITU"
                      : aiZostalo === undefined ? undefined
                      : aiZostalo > 0 ? `${aiZostalo} DARMOWY ODCZYT` : "WYKORZYSTANE"
                  }
                  przygaszony={aiZostalo === 0}
                  onPress={() => wybierz("ai")}
                />

                <Duzy
                  ikona="recznie"
                  tytul="Wpisz pozycje ręcznie"
                  opis="Kilka walorów wpiszesz szybciej, niż znajdziesz plik. Kurs i tak pobieramy z rynku."
                  kolor={C.accent}
                  onPress={() => wybierz("recznie")}
                />
              </>
            )}
          </ScrollView>
        </View>
      </View>
    </Modal>
  );
}

function Duzy({ ikona, tytul, opis, kolor, onPress, odznaka, przygaszony }: {
  ikona: IconName; tytul: string; opis: string; kolor: string;
  onPress: () => void; odznaka?: string; przygaszony?: boolean;
}) {
  return (
    <Pressable onPress={onPress} style={({ pressed }) => [
      s.duzy, { borderColor: kolor + "55" },
      pressed && { backgroundColor: kolor + "12", borderColor: kolor },
      przygaszony && { opacity: 0.55 },
    ]}>
      <View style={[s.duzyIkona, { backgroundColor: kolor + "1c" }]}>
        <Icon name={ikona} size={22} color={kolor} />
      </View>
      <View style={{ flex: 1 }}>
        <View style={s.duzyGlowa}>
          <Text style={s.duzyTytul}>{tytul}</Text>
          {!!odznaka && (
            <View style={[s.odznaka, { borderColor: kolor + "77", backgroundColor: kolor + "18" }]}>
              <Text style={[s.odznakaTxt, { color: kolor }]}>{odznaka}</Text>
            </View>
          )}
        </View>
        <Text style={s.duzyOpis}>{opis}</Text>
      </View>
      <Text style={[s.strzalka, { color: kolor }]}>›</Text>
    </Pressable>
  );
}

function Kafel({ broker, onPress }: { broker: Broker; onPress: () => void }) {
  const czynny = !!broker.dziala;
  return (
    <Pressable onPress={czynny ? onPress : undefined} disabled={!czynny}
               style={({ pressed }) => [
                 s.kafel,
                 czynny && s.kafelCzynny,
                 czynny && pressed && { backgroundColor: "rgba(255,92,108,.16)" },
               ]}>
      <Text style={[s.kafelNazwa, czynny && { color: C.text }]} numberOfLines={1}>
        {broker.nazwa}
      </Text>
      <Text style={[s.kafelNota, czynny && { color: C.red }]} numberOfLines={1}>
        {czynny ? broker.nota : "przez AI"}
      </Text>
    </Pressable>
  );
}

const s = StyleSheet.create({
  tlo: { flex: 1, backgroundColor: "rgba(0,0,0,.74)", justifyContent: "flex-end" },
  okno: {
    backgroundColor: C.bg, borderTopLeftRadius: 22, borderTopRightRadius: 22,
    maxHeight: "90%", borderTopWidth: 1, borderColor: C.border2,
    width: "100%", maxWidth: 620, alignSelf: "center",
  },
  glowa: {
    flexDirection: "row", alignItems: "center", gap: 12,
    padding: 18, paddingBottom: 14, borderBottomWidth: 1, borderBottomColor: C.border,
  },
  wstecz: { color: C.muted, fontSize: 26, fontWeight: "800", marginTop: -4 },
  tytul: { color: C.text, ...T.h1 },
  podtytul: { color: C.dim, fontSize: 12, lineHeight: 16, marginTop: 3 },
  x: {
    width: 32, height: 32, borderRadius: 10, borderWidth: 1, borderColor: C.border2,
    alignItems: "center", justifyContent: "center", backgroundColor: C.card,
  },
  tresc: { padding: 16, gap: 11, paddingBottom: 34 },

  duzy: {
    flexDirection: "row", alignItems: "center", gap: 13,
    backgroundColor: C.card, borderWidth: 1, borderRadius: 15, padding: 14,
  },
  duzyIkona: {
    width: 46, height: 46, borderRadius: 14,
    alignItems: "center", justifyContent: "center",
  },
  duzyGlowa: { flexDirection: "row", alignItems: "center", gap: 8, flexWrap: "wrap" },
  duzyTytul: { color: C.text, fontSize: 15, fontWeight: "800" },
  duzyOpis: { color: C.dim, fontSize: 11.5, lineHeight: 16, marginTop: 4 },
  strzalka: { fontSize: 22, fontWeight: "800" },
  odznaka: { borderRadius: 999, borderWidth: 1, paddingHorizontal: 7, paddingVertical: 2 },
  odznakaTxt: { fontSize: 8.5, fontWeight: "800", letterSpacing: 0.6 },

  siatka: { flexDirection: "row", flexWrap: "wrap", gap: 8 },
  kafel: {
    flexGrow: 1, flexBasis: "30%", backgroundColor: C.elev,
    borderWidth: 1, borderColor: C.border, borderRadius: 12,
    paddingVertical: 11, paddingHorizontal: 10, gap: 2,
  },
  /** XTB świeci na czerwono, bo to jedyny broker, którego raport czytamy
   *  co do kolumny — i chcemy, żeby wzrok padł na niego pierwszy. */
  kafelCzynny: { borderColor: C.red, backgroundColor: "rgba(255,92,108,.10)" },
  kafelNazwa: { color: C.dim, fontSize: 12, fontWeight: "700" },
  kafelNota: { color: C.dim, fontSize: 9, opacity: 0.85 },
  kreska: { height: 1, backgroundColor: C.border, marginVertical: 6 },
});
