/** „przed chwilą" / „3 min temu" — krótkie i czytelne na wąskim ekranie. */
export function ago(seconds: number): string {
  if (seconds < 5) return "przed chwilą";
  if (seconds < 60) return `${Math.round(seconds)} s temu`;
  if (seconds < 3600) return `${Math.round(seconds / 60)} min temu`;
  return `${Math.round(seconds / 3600)} h temu`;
}

export function every(interval: number): string {
  if (interval < 60) return `co ${interval} s`;
  if (interval < 3600) return `co ${Math.round(interval / 60)} min`;
  return `co ${Math.round(interval / 3600)} h`;
}
