/** Bot newsowy — sygnały, sterowanie i Mózg AI w jednym miejscu. */
import React, { useCallback, useEffect, useRef, useState } from "react";
import {
  ActivityIndicator, AppState, RefreshControl, ScrollView, StyleSheet, Text, View,
} from "react-native";
import { BotState, getBotState, getSkrzynka, getSummary, Position } from "../api";
import { useAuth } from "../auth/AuthContext";
import PremiumGate from "../components/PremiumGate";
import { C, T } from "../theme";
import { Card, FadeIn, LiquidButton, MetalButton, Press, Segmented } from "../ui";
import BotShowcase from "./bot/BotShowcase";
import BrainTab from "./bot/BrainTab";
import NotifyInbox from "./bot/NotifyInbox";
import NotifyPanel from "./bot/NotifyPanel";
import Icon from "../ui/Icon";
import ControlTab from "./bot/ControlTab";
import SignalsTab from "./bot/SignalsTab";
import SourcesTab from "./bot/SourcesTab";
import { TAB_SPACE } from "../layout";

const TABS = [
  { id: "signals", label: "Analizy" },
  { id: "sources", label: "Źródła" },
  { id: "control", label: "Sterowanie" },
  { id: "brain", label: "Mózg AI" },
];

export default function BotScreen() {
  const { ready, catalog, me, locked } = useAuth();

  /** Bez premium ten ekran w ogóle nie jest ekranem z zakładkami — jest wizytówką.
   *
   *  Zasłanianie zakładek kłódkami dawało puste ramki: człowiek widział, że czegoś
   *  nie ma, ale nie widział, czego. Teraz dostaje osobny ekran, który pokazuje
   *  działający nasłuch i ścieżkę decyzji, a płatnej treści po prostu nie pobiera.
   *
   *  PUŁAPKA, przez którą to musi czekać na `ready`: `locked()` celowo zwraca
   *  `false`, dopóki katalog funkcji się nie wczyta (żeby kłódki nie migotały przy
   *  starcie). Bez tego warunku ekran zdążyłby w tym czasie zapytać o płatne
   *  `/api/state` — a gościowi bez konta serwer odpowiada 401, co otwiera okno
   *  logowania na wierzchu strony sprzedażowej. Czyli dokładnie ślepa uliczka,
   *  którą ta zmiana miała usunąć.
   *
   *  Gdy katalog w ogóle nie dojechał, decyduje sam status konta — gość widzi
   *  wizytówkę, nie błąd. */
  const wizytowka = ready && (catalog ? locked("bot.signals") : !me?.premium);

  const [tab, setTab] = useState("signals");
  const [st, setSt] = useState<BotState | null>(null);
  const [positions, setPositions] = useState<Position[]>([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  // Skrzynka powiadomień: licznik w nagłówku, treść w oknie na wierzchu.
  const [skrzynka, setSkrzynka] = useState(false);
  const [nieprzeczytane, setNieprzeczytane] = useState(0);

  const load = useCallback(async () => {
    // dopóki nie wiadomo, kim jest widz, nie ruszamy płatnych endpointów;
    // ekran zostaje na kręciołku, a nie na tabach z pustym stanem
    if (!ready) return;
    if (wizytowka) { setLoading(false); setBusy(false); return; }
    try {
      const s = await getBotState();
      setSt(s);
      setErr("");
    } catch (e: any) {
      setErr(e?.message || "Błąd połączenia");
    } finally {
      setLoading(false);
      setBusy(false);
    }
  }, [ready, wizytowka]);

  /* Licznik nieprzeczytanych. Pobieramy sam licznik razem ze stanem bota, a nie
     w osobnym rytmie — jeden przebieg odświeżania zamiast dwóch niezależnych. */
  useEffect(() => {
    if (!ready || wizytowka || skrzynka) return;
    getSkrzynka(1).then((r) => setNieprzeczytane(r.unread)).catch(() => {});
  }, [ready, wizytowka, skrzynka, st]);

  // pozycje z portfela — potrzebne do filtra „moje spółki" w sygnałach
  useEffect(() => {
    if (!ready || wizytowka) return;
    getSummary().then((s) => { if (!s.empty) setPositions(s.positions); }).catch(() => {});
  }, [ready, wizytowka]);

  useEffect(() => { load(); }, [load]);

  // odświeżamy na zakładkach, które pokazują dane na żywo (analizy, liczniki źródeł).
  // Sterowanie i Mózg mają własny stan edycji, którego nie wolno nadpisać w trakcie pisania.
  const tabRef = useRef(tab);
  tabRef.current = tab;
  useEffect(() => {
    if (wizytowka) return;               // wizytówka odświeża się sama, własnym rytmem
    let timer: ReturnType<typeof setInterval> | null = null;
    const start = () => {
      if (timer) return;
      timer = setInterval(() => {
        if (tabRef.current === "signals" || tabRef.current === "sources") load();
      }, 20000);
    };
    const stop = () => { if (timer) { clearInterval(timer); timer = null; } };
    const sub = AppState.addEventListener("change", (s) => {
      if (s === "active") { load(); start(); } else stop();
    });
    start();
    return () => { stop(); sub.remove(); };
  }, [load, wizytowka]);

  if (wizytowka) return <BotShowcase />;

  if (loading) {
    return <View style={s.center}><ActivityIndicator color={C.green} size="large" /></View>;
  }
  if (err && !st) {
    return (
      <View style={s.center}>
        <Text style={s.errTitle}>{err}</Text>
        <LiquidButton label="Spróbuj ponownie" full={false} style={{ minWidth: 220 }}
                      onPress={() => { setLoading(true); load(); }} />
      </View>
    );
  }

  const running = st?.bot_alive;
  const killed = Boolean(st?.params?.kill_switch);

  return (
    <ScrollView
      contentContainerStyle={s.wrap}
      showsVerticalScrollIndicator={false}
      keyboardShouldPersistTaps="handled"
      refreshControl={
        <RefreshControl refreshing={busy} tintColor={C.green}
                        onRefresh={() => { setBusy(true); load(); }} />
      }
    >
      <FadeIn>
        <View style={s.head}>
          <View style={{ flex: 1 }}>
            <Text style={s.h1}>Bot newsowy</Text>
            <Text style={s.sub}>Nasłuch źródeł i analiza AI</Text>
          </View>
          <View style={[s.status, {
            backgroundColor: killed ? "rgba(255,92,108,.12)"
              : running ? C.greenDim : "rgba(139,147,167,.1)",
          }]}>
            <View style={[s.dot, {
              backgroundColor: killed ? C.red : running ? C.green : C.dim,
            }]} />
            <Text style={[s.statusTxt, {
              color: killed ? C.red : running ? C.green : C.muted,
            }]}>
              {killed ? "ZATRZYMANY" : running ? "NASŁUCH" : "STOP"}
            </Text>
          </View>

          {/* Dzwonek stoi obok stanu nasłuchu, bo odpowiada na sąsiednie pytanie:
              tamten mówi, czy bot słucha, ten — czy coś do MNIE przyszło. */}
          <Press style={s.dzwonek} onPress={() => setSkrzynka(true)}>
            <Icon name="dzwonek" size={16}
                  color={nieprzeczytane ? C.green : C.muted} />
            {nieprzeczytane > 0 && (
              <View style={s.licznik}>
                <Text style={s.licznikTxt}>
                  {nieprzeczytane > 9 ? "9+" : nieprzeczytane}
                </Text>
              </View>
            )}
          </Press>
        </View>
      </FadeIn>

      {skrzynka && <NotifyInbox onZamknij={() => { setSkrzynka(false); setNieprzeczytane(0); }} />}

      {/* Powiadomienia stoją NAD zakładkami i to jest celowe: nasłuch jest wspólny
          dla serwera, więc wchodzący nie ma na niego wpływu i przy zatrzymanym
          bocie widział pustą stronę. To jedyna rzecz, którą może tu ustawić dla
          siebie — i najczęstszy powód, dla którego ktoś w ogóle tu wraca. */}
      <NotifyPanel />

      <View style={{ marginTop: 16, marginBottom: 4 }}>
        <Segmented options={TABS} value={tab} onChange={setTab} />
      </View>

      {/* Sterowanie zostaje otwarte — to bezpiecznik, a nie funkcja sprzedażowa.
          Płatne są sygnały (treść) i Mózg AI (konfiguracja modelu). */}
      {tab === "signals" && (
        <PremiumGate id="bot.signals" minHeight={340} style={{ marginTop: 14 }}>
          <SignalsTab signals={st?.signals || []} positions={positions}
                      outcomes={st?.outcomes} running={Boolean(running)} />
        </PremiumGate>
      )}
      {tab === "sources" && st && <SourcesTab st={st} reload={load} />}
      {tab === "control" && st && <ControlTab st={st} reload={load} />}
      {tab === "brain" && (
        <PremiumGate id="bot.brain" minHeight={340} style={{ marginTop: 14 }}>
          <BrainTab />
        </PremiumGate>
      )}
    </ScrollView>
  );
}

const s = StyleSheet.create({
  wrap: { padding: 18, paddingTop: 8, paddingBottom: TAB_SPACE },
  center: { flex: 1, alignItems: "center", justifyContent: "center", padding: 30, gap: 12 },
  errTitle: { color: C.text, ...T.h2, textAlign: "center" },
  retry: { backgroundColor: C.green, borderRadius: 13, paddingVertical: 13, paddingHorizontal: 26 },
  retryTxt: { color: "#04140c", fontWeight: "800", fontSize: 15 },

  head: { flexDirection: "row", alignItems: "center" },
  h1: { color: C.text, ...T.h1 },
  sub: { color: C.muted, ...T.small, marginTop: 3 },
  status: {
    flexDirection: "row", alignItems: "center", gap: 7,
    borderRadius: 999, paddingHorizontal: 11, paddingVertical: 6,
  },
  dot: { width: 7, height: 7, borderRadius: 4 },
  dzwonek: {
    width: 34, height: 34, borderRadius: 12, marginLeft: 8,
    backgroundColor: C.elev, borderWidth: 1, borderColor: C.border2,
    alignItems: "center", justifyContent: "center",
  },
  licznik: {
    position: "absolute", top: -3, right: -3, minWidth: 16, height: 16,
    borderRadius: 8, backgroundColor: C.green, paddingHorizontal: 4,
    alignItems: "center", justifyContent: "center",
  },
  licznikTxt: { color: "#04140c", fontSize: 9.5, fontWeight: "800" },
  statusTxt: { fontSize: 10.5, fontWeight: "800", letterSpacing: 0.6 },
});
