/** Dodawanie majątku i odczyt raportu przez AI — dwa okna za wyborem z ImportChooser.
 *
 *  Formularz majątku ma jedną rzecz, o którą warto zawalczyć: **kategoria
 *  wybiera sposób wyceny za użytkownika.** Złoto i krypto dostają wycenę
 *  rynkową z gotowym symbolem, mieszkanie i działka wycenę ręczną. Nikt nie
 *  musi wiedzieć, czym jest „GC=F", żeby wpisać, że ma pół kilo złota.
 *
 *  **Metale wpisuje się tak, jak się je ma.** Nikt nie kupuje „0,3215 uncji" —
 *  kupuje się sztabkę 10 g, monetę jednouncjową albo „za dwadzieścia tysięcy".
 *  Dlatego są trzy pola do wyboru (uncje, gramy, złotówki), a przeliczeniem po
 *  bieżącym kursie zajmuje się formularz. W bazie i tak ląduje ilość w uncjach,
 *  bo to jednostka notowania — i dzięki temu śledzenie złota jest banalnie
 *  proste: ilość razy kurs, ten sam kod co dla akcji.
 */
import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  ActivityIndicator, Animated, Easing, Modal, Pressable, ScrollView,
  StyleSheet, Text, TextInput, View,
} from "react-native";
import { wybierzPlik as otworzPicker } from "../filePicker";
import {
  AiOdczyt, czytajRaportAi, dodajAktywo, getSpot, getWealth, getWealthMeta,
  WealthMeta, WealthPortfel, WealthSpot,
} from "../api";
import { C, fmtNum, fmtPLN, fmtPLN0, T } from "../theme";
import { MetalButton } from "../ui";
import Icon, { maIkone } from "../ui/Icon";
import { Domek, Metal, Moneta, TypNieruchomosci } from "./WealthArt";

/* =========================================================== majątek */

/** Metale, które umiemy wycenić z rynku — symbol notowania i kolor monety. */
const METALE: { id: Metal; nazwa: string; symbol: string; domyslna: string }[] = [
  { id: "zloto", nazwa: "Złoto", symbol: "GC=F", domyslna: "Złoto inwestycyjne" },
  { id: "srebro", nazwa: "Srebro", symbol: "SI=F", domyslna: "Srebro inwestycyjne" },
  { id: "platyna", nazwa: "Platyna", symbol: "PL=F", domyslna: "Platyna" },
];

/** Rodzaje nieruchomości — wybór podstawia nazwę, żeby nie zaczynać od pustego pola. */
const NIERUCHOMOSCI: { id: TypNieruchomosci; nazwa: string; domyslna: string }[] = [
  { id: "mieszkanie", nazwa: "Mieszkanie", domyslna: "Mieszkanie" },
  { id: "dom", nazwa: "Dom", domyslna: "Dom" },
  { id: "dzialka", nazwa: "Działka", domyslna: "Działka" },
  { id: "lokal", nazwa: "Lokal", domyslna: "Lokal usługowy" },
];

/** Jak wpisujesz ilość metalu. Uncja jest jednostką notowania, ale prawie nikt
 *  nie myśli w uncjach — stąd gramy i złotówki, przeliczane po bieżącym kursie. */
const MIARY = [
  { id: "uncje", label: "Uncje", sufiks: "oz" },
  { id: "gramy", label: "Gramy", sufiks: "g" },
  { id: "zlote", label: "Za ile kupiłem", sufiks: "zł" },
] as const;
type Miara = typeof MIARY[number]["id"];

const num = (v: string) => {
  const x = Number((v || "").replace(/\s/g, "").replace(",", "."));
  return isFinite(x) ? x : 0;
};

export function AssetForm({ widoczne, zamknij, gotowe, kategoriaStart }: {
  widoczne: boolean; zamknij: () => void; gotowe: () => void;
  /** „akcje" przy wejściu z „wpisz ręcznie", pusto przy wejściu z „majątek" */
  kategoriaStart?: string;
}) {
  const [meta, setMeta] = useState<WealthMeta | null>(null);
  const [portfele, setPortfele] = useState<WealthPortfel[]>([]);
  const [kategoria, setKategoria] = useState(kategoriaStart || "nieruchomosc");
  const [metal, setMetal] = useState<Metal>("zloto");
  const [typNier, setTypNier] = useState<TypNieruchomosci>("mieszkanie");
  const [miara, setMiara] = useState<Miara>("gramy");
  const [portfel, setPortfel] = useState<string>("");
  const [nazwa, setNazwa] = useState("");
  const [symbol, setSymbol] = useState("");
  const [ilosc, setIlosc] = useState("");
  const [wartosc, setWartosc] = useState("");
  const [koszt, setKoszt] = useState("");
  const [spot, setSpot] = useState<WealthSpot | null>(null);
  const [spotBusy, setSpotBusy] = useState(false);
  const [busy, setBusy] = useState(false);
  const [blad, setBlad] = useState("");

  useEffect(() => {
    if (!widoczne) return;
    getWealthMeta().then(setMeta).catch(() => {});
    // Lista portfeli tylko po to, żeby dało się od razu wskazać właściwy.
    // Gdy nie ma ani jednego, wybór się nie pokazuje — pytanie „do którego
    // portfela" przy jednym portfelu jest pytaniem o nic.
    getWealth().then((w) => setPortfele(w.portfele)).catch(() => {});
  }, [widoczne]);

  useEffect(() => {
    if (widoczne) {
      setKategoria(kategoriaStart || "nieruchomosc");
      setMetal("zloto"); setTypNier("mieszkanie"); setMiara("gramy"); setPortfel("");
      setNazwa(""); setSymbol(""); setIlosc(""); setWartosc(""); setKoszt("");
      setBlad(""); setSpot(null);
    }
  }, [widoczne, kategoriaStart]);

  // Kategoria decyduje o sposobie wyceny. Wystawianie tego wyboru użytkownikowi
  // byłoby pytaniem, na które musiałby znać odpowiedź, żeby móc odpowiedzieć.
  const rynkowa = ["akcje", "etf", "metal", "krypto"].includes(kategoria);
  const jestMetal = kategoria === "metal";
  const jestNier = kategoria === "nieruchomosc";
  const podpowiedzi = (meta?.symbole || []).filter((s) => s.kategoria === kategoria);

  // Symbol dla metalu wynika z wyboru monety, a nie z wpisywania — „GC=F" to
  // wiedza, której nikt nie musi mieć, żeby powiedzieć, że ma złoto.
  const symbolAktywny = jestMetal
    ? (METALE.find((m) => m.id === metal)?.symbol || "GC=F")
    : symbol.trim().toUpperCase();

  // Kurs pobieramy przy każdej zmianie symbolu — bez niego gramy i złotówki nie
  // mają jak zamienić się w uncje, a podgląd wartości nie miałby z czego powstać.
  useEffect(() => {
    if (!widoczne || !rynkowa || !symbolAktywny) { setSpot(null); return; }
    let zywe = true;
    setSpotBusy(true);
    getSpot(symbolAktywny)
      .then((x) => { if (zywe) setSpot(x); })
      .catch(() => { if (zywe) setSpot(null); })
      .finally(() => { if (zywe) setSpotBusy(false); });
    return () => { zywe = false; };
  }, [widoczne, rynkowa, symbolAktywny]);

  /** Ilość w jednostce notowania (uncje dla metali, sztuki dla reszty). */
  const iloscDocelowa = useMemo(() => {
    const v = num(ilosc);
    if (!jestMetal) return v;
    if (miara === "uncje") return v;
    if (miara === "gramy") return v / (spot?.gram_w_uncji || 31.1034768);
    return spot?.pln ? v / spot.pln : 0;   // wpisana kwota → uncje po kursie
  }, [ilosc, miara, jestMetal, spot]);

  const podgladWartosci = spot?.pln ? iloscDocelowa * spot.pln : null;

  const zapisz = async () => {
    setBusy(true); setBlad("");
    try {
      const domyslnaNazwa = jestMetal
        ? (METALE.find((m) => m.id === metal)?.domyslna || "Metal")
        : jestNier
          ? (NIERUCHOMOSCI.find((n) => n.id === typNier)?.domyslna || "Nieruchomość")
          : (meta?.kategorie.find((k) => k.id === kategoria)?.nazwa ?? "Aktywo");
      await dodajAktywo({
        nazwa: nazwa.trim() || domyslnaNazwa,
        kategoria,
        portfel_id: portfel || null,
        wycena: rynkowa ? "auto" : "manual",
        symbol: rynkowa ? symbolAktywny : "",
        ilosc: rynkowa ? iloscDocelowa : 0,
        wartosc: num(wartosc),
        koszt: num(koszt) || (jestMetal && miara === "zlote" ? num(ilosc) : 0),
        notatka: jestNier ? typNier : "",
      });
      gotowe(); zamknij();
    } catch (e: any) {
      setBlad(e?.message || "Nie udało się zapisać");
    } finally { setBusy(false); }
  };

  const uwagaKategorii = (meta?.kategorie || []).find((k) => k.id === kategoria)?.uwaga;

  const mozna = rynkowa
    ? (jestMetal ? iloscDocelowa > 0 : !!symbolAktywny && num(ilosc) > 0)
    : !!nazwa.trim() && num(wartosc) > 0;

  return (
    <Okno widoczne={widoczne} zamknij={zamknij} tytul="Dodaj do majątku"
          podtytul="Policzy się razem z portfelem maklerskim">
      <Text style={s.etykieta}>Co to jest</Text>
      <View style={s.siatka}>
        {(meta?.kategorie || []).map((k) => (
          <Pressable key={k.id} onPress={() => { setKategoria(k.id); setSymbol(""); setIlosc(""); }}
                     style={[s.kat, kategoria === k.id && s.katOn]}>
            {maIkone(k.ikona) && (
              <Icon name={k.ikona} size={19} color={kategoria === k.id ? C.green : C.muted} />
            )}
            <Text style={[s.katTxt, kategoria === k.id && { color: C.green }]}
                  numberOfLines={1}>{k.nazwa}</Text>
          </Pressable>
        ))}
      </View>

      {/* Ostrzeżenie dla kategorii, które da się wpisać ręcznie, ale prawie
          zawsze lepiej wczytać z raportu. Pokazuje się dopiero PO wybraniu
          kafelka, a nie z góry przy wszystkich — ostrzeżenie widoczne, zanim
          ktokolwiek cokolwiek wybrał, czyta się jak ostrzeżenie przed całym
          formularzem. */}
      {!!uwagaKategorii && (
        <View style={s.uwagaKat}>
          <Icon name="uwaga" size={13} color={C.amber} />
          <Text style={s.uwagaKatTxt}>{uwagaKategorii}</Text>
        </View>
      )}

      {jestMetal ? (
        <>
          <Moneta metal={metal} />
          <View style={s.chipsy}>
            {METALE.map((m) => (
              <Pressable key={m.id} onPress={() => setMetal(m.id)}
                         style={[s.chip, metal === m.id && s.chipOn]}>
                <Text style={[s.chipTxt, metal === m.id && { color: C.green }]}>{m.nazwa}</Text>
              </Pressable>
            ))}
          </View>

          <View style={s.kurs}>
            {spotBusy && !spot ? (
              <ActivityIndicator color={C.gold} size="small" />
            ) : spot?.pln ? (
              <>
                <Text style={s.kursDuzy}>{fmtPLN0(spot.pln)} zł</Text>
                <Text style={s.kursOpis}>
                  za uncję · {fmtPLN0(spot.pln_gram || 0)} zł za gram
                  {spot.kurs ? ` · ${fmtNum(spot.kurs, 2)} ${spot.waluta}` : ""}
                </Text>
              </>
            ) : (
              <Text style={s.kursOpis}>Kurs chwilowo niedostępny — ilość i tak zapiszemy</Text>
            )}
          </View>

          <Text style={s.info}>
            Śledzenie metalu jest najprostsze, jakie mamy: zapamiętujemy ilość,
            a wartość liczy się z bieżącego kursu — codziennie, bez wpisywania
            czegokolwiek. Wpisz to, co wiesz.
          </Text>

          <View style={{ marginTop: 12 }}>
            <View style={s.miary}>
              {MIARY.map((m) => (
                <Pressable key={m.id} onPress={() => { setMiara(m.id); setIlosc(""); }}
                           style={[s.miara, miara === m.id && s.miaraOn]}>
                  <Text style={[s.miaraTxt, miara === m.id && { color: C.bg }]}>{m.label}</Text>
                </Pressable>
              ))}
            </View>
            <Pole
              etykieta={miara === "uncje" ? "Ile uncji"
                : miara === "gramy" ? "Ile gramów" : "Za ile kupiłeś"}
              wartosc={ilosc} zmien={setIlosc} numer
              sufiks={MIARY.find((m) => m.id === miara)?.sufiks}
              placeholder={miara === "uncje" ? "np. 1" : miara === "gramy" ? "np. 100" : "np. 20000"}
            />
          </View>

          {iloscDocelowa > 0 && (
            <View style={s.przelicz}>
              <Text style={s.przeliczTxt}>
                To <Text style={s.mocny}>{fmtNum(iloscDocelowa, 4)} oz</Text>
                {spot?.gram_w_uncji
                  ? ` (${fmtNum(iloscDocelowa * spot.gram_w_uncji, 2)} g)` : ""}
              </Text>
              {podgladWartosci !== null && (
                <Text style={s.przeliczKwota}>≈ {fmtPLN(podgladWartosci)} dziś</Text>
              )}
            </View>
          )}
        </>
      ) : jestNier ? (
        <>
          <Domek typ={typNier} />
          <View style={s.chipsy}>
            {NIERUCHOMOSCI.map((n) => (
              <Pressable key={n.id}
                         onPress={() => {
                           setTypNier(n.id);
                           // nazwa idzie za wyborem tylko dopóki jej nie ruszyłeś
                           const stara = NIERUCHOMOSCI.find((x) => x.id === typNier)?.domyslna;
                           if (!nazwa.trim() || nazwa === stara) setNazwa(n.domyslna);
                         }}
                         style={[s.chip, typNier === n.id && s.chipOn]}>
                <Text style={[s.chipTxt, typNier === n.id && { color: C.green }]}>{n.nazwa}</Text>
              </Pressable>
            ))}
          </View>

          <Pole etykieta="Jak to nazwiesz" wartosc={nazwa} zmien={setNazwa}
                placeholder="np. Mieszkanie na Mokotowie" />
          <Pole etykieta="Ile jest dziś warte" wartosc={wartosc} zmien={setWartosc}
                placeholder="np. 700000" numer sufiks="zł" />

          <View style={s.uwaga}>
            <Text style={s.uwagaTxt}>
              <Text style={s.mocny}>Mieszkania nie mają kursu</Text> — i nie będziemy
              udawać, że mają. Wartość zostaje ta, którą wpisałeś, a obok niej
              policzymy, ile ta sama kwota znaczy dziś po inflacji. To podpowiedź:
              zamieni się w wycenę dopiero wtedy, gdy ją zatwierdzisz. Kolejne
              wyceny dopiszesz w każdej chwili — z nich powstanie wykres wartości
              w czasie.
            </Text>
          </View>
        </>
      ) : rynkowa ? (
        <>
          <Text style={s.info}>
            Wyceniamy z rynku — podaj symbol i ilość, a wartość policzy się sama
            i będzie się aktualizować.
          </Text>
          {podpowiedzi.length > 0 && (
            <View style={s.chipsy}>
              {podpowiedzi.map((p) => (
                <Pressable key={p.symbol} onPress={() => { setSymbol(p.symbol); setNazwa(p.nazwa); }}
                           style={[s.chip, symbol === p.symbol && s.chipOn]}>
                  <Text style={[s.chipTxt, symbol === p.symbol && { color: C.green }]}>
                    {p.nazwa}
                  </Text>
                </Pressable>
              ))}
            </View>
          )}
          <Pole etykieta="Symbol" wartosc={symbol} zmien={setSymbol}
                placeholder="np. BTC-USD, CDR.WA" />
          <Pole etykieta="Ile sztuk" wartosc={ilosc} zmien={setIlosc}
                placeholder="np. 0,212" numer />
          {podgladWartosci !== null && num(ilosc) > 0 && (
            <View style={s.przelicz}>
              <Text style={s.przeliczTxt}>Kurs {fmtPLN0(spot!.pln || 0)} zł za sztukę</Text>
              <Text style={s.przeliczKwota}>≈ {fmtPLN(podgladWartosci)} dziś</Text>
            </View>
          )}
          <Pole etykieta="Nazwa (opcjonalnie)" wartosc={nazwa} zmien={setNazwa}
                placeholder="np. Bitcoin z giełdy" />
        </>
      ) : (
        <>
          <Text style={s.info}>
            Tego nie da się wycenić z rynku, więc wartość podajesz sam. Kolejne
            wyceny dopiszesz później — z nich powstanie wykres wartości w czasie.
          </Text>
          <Pole etykieta="Nazwa" wartosc={nazwa} zmien={setNazwa}
                placeholder="np. Obligacje EDO, zegarek, samochód" />
          <Pole etykieta="Ile jest dziś warte" wartosc={wartosc} zmien={setWartosc}
                placeholder="np. 12000" numer sufiks="zł" />
        </>
      )}

      {!(jestMetal && miara === "zlote") && (
        <Pole etykieta="Ile kosztowało (opcjonalnie)" wartosc={koszt} zmien={setKoszt}
              placeholder="bez tego nie policzymy zysku" numer sufiks="zł" />
      )}

      {portfele.length > 0 && (
        <View style={{ marginTop: 14 }}>
          <Text style={s.etykieta}>Do którego portfela</Text>
          <View style={s.chipsy}>
            <Pressable onPress={() => setPortfel("")}
                       style={[s.chip, !portfel && s.chipOn]}>
              <Text style={[s.chipTxt, !portfel && { color: C.green }]}>Bez przypisania</Text>
            </Pressable>
            {portfele.map((p) => (
              <Pressable key={p.id} onPress={() => setPortfel(p.id)}
                         style={[s.chip, portfel === p.id && s.chipOn]}>
                <Text style={[s.chipTxt, portfel === p.id && { color: C.green }]}>{p.nazwa}</Text>
              </Pressable>
            ))}
          </View>
        </View>
      )}

      {!!blad && <Text style={s.blad}>{blad}</Text>}
      <View style={{ marginTop: 16 }}>
        <MetalButton label={busy ? "Zapisuję…" : "Dodaj do majątku"}
                     onPress={mozna && !busy ? zapisz : () => {}}
                     tone={mozna ? "green" : "steel"} />
      </View>
    </Okno>
  );
}

/* =========================================================== raport AI */

const KROKI = [
  "Czytam plik…",
  "Rozpoznaję układ kolumn…",
  "Wypisuję pozycje…",
  "Sprawdzam liczby…",
];

export function AiReport({ widoczne, zamknij, gotowe }: {
  widoczne: boolean; zamknij: () => void; gotowe: () => void;
}) {
  const [stan, setStan] = useState<"wybor" | "liczy" | "wynik" | "blad">("wybor");
  const [krok, setKrok] = useState(0);
  const [wynik, setWynik] = useState<AiOdczyt | null>(null);
  const [blad, setBlad] = useState("");
  const obrot = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    if (stan !== "liczy") return;
    // Kółko kręci się bez przerwy, a podpis zmienia się co trzy sekundy.
    // Sam spinner przy czterdziestu sekundach oczekiwania wygląda jak zawieszenie;
    // zmieniający się opis mówi, że coś się dzieje, choć nie znamy postępu.
    const anim = Animated.loop(Animated.timing(obrot, {
      toValue: 1, duration: 1100, easing: Easing.linear, useNativeDriver: true,
    }));
    anim.start();
    const t = setInterval(() => setKrok((k) => (k + 1) % KROKI.length), 3000);
    return () => { anim.stop(); clearInterval(t); };
  }, [stan]);

  useEffect(() => { if (widoczne) { setStan("wybor"); setWynik(null); setBlad(""); setKrok(0); } },
            [widoczne]);

  const wybierzPlik = useCallback(async () => {
    try {
      const res = await otworzPicker({ copyToCacheDirectory: true });
      if (res.canceled || !res.assets?.length) return;
      const a = res.assets[0];
      setStan("liczy"); setKrok(0);

      const odp = await fetch(a.uri);
      const buf = await odp.arrayBuffer();
      let bin = "";
      const bytes = new Uint8Array(buf);
      for (let i = 0; i < bytes.length; i += 8192) {
        bin += String.fromCharCode(...bytes.subarray(i, i + 8192));
      }
      const wynikAi = await czytajRaportAi(a.name || "raport", btoa(bin));
      setWynik(wynikAi); setStan("wynik");
    } catch (e: any) {
      setBlad(e?.message || "Nie udało się odczytać pliku");
      setStan("blad");
    }
  }, []);

  return (
    <Okno widoczne={widoczne} zamknij={zamknij} tytul="Odczyt raportu przez AI"
          podtytul="Dla brokerów, których jeszcze nie umiemy czytać">
      {stan === "wybor" && (
        <>
          <Text style={s.info}>
            Wybierz plik z historią rachunku w dowolnym formacie — CSV, arkusz,
            wyciąg. Model przeczyta go i wypisze pozycje, a Ty je zobaczysz
            i zatwierdzisz przed dodaniem do portfela.
          </Text>
          <View style={s.uwaga}>
            <Text style={s.uwagaTxt}>
              Odczyt maszynowy bywa omylny — dlatego <Text style={s.mocny}>nic nie
              wchodzi do portfela automatycznie</Text>. Zawsze pokazujemy, co
              zostało odczytane, zanim cokolwiek zapiszemy.
            </Text>
          </View>
          <View style={{ marginTop: 16 }}>
            <MetalButton label="Wybierz plik" onPress={wybierzPlik} tone="green" />
          </View>
        </>
      )}

      {stan === "liczy" && (
        <View style={s.liczy}>
          <Animated.View style={[s.kolo, {
            transform: [{ rotate: obrot.interpolate({ inputRange: [0, 1], outputRange: ["0deg", "360deg"] }) }],
          }]}>
            <View style={s.koloLuk} />
          </Animated.View>
          <Text style={s.liczyTytul}>{KROKI[krok]}</Text>
          <Text style={s.liczyOpis}>
            Duży raport potrafi zająć minutę. Nie zamykaj tego okna — jeśli
            model nie odpowie, spróbujemy kolejnym.
          </Text>
        </View>
      )}

      {stan === "wynik" && wynik && (
        <>
          <View style={s.podsum}>
            <Text style={s.podsumDuza}>{wynik.pozycje.length}</Text>
            <Text style={s.podsumOpis}>
              {wynik.pozycje.length === 1 ? "odczytana pozycja" : "odczytanych pozycji"}
              {wynik.broker ? ` · rozpoznany broker: ${wynik.broker}` : ""}
            </Text>
          </View>

          {wynik.pewnosc !== null && wynik.pewnosc < 0.7 && (
            <View style={s.uwaga}>
              <Text style={s.uwagaTxt}>
                Model nie jest pewien tego odczytu. Sprawdź liczby uważnie,
                zanim je zatwierdzisz.
              </Text>
            </View>
          )}
          {!!wynik.uwagi && <Text style={s.info}>{wynik.uwagi}</Text>}

          <ScrollView style={{ maxHeight: 280 }} contentContainerStyle={{ gap: 7 }}>
            {wynik.pozycje.map((p, i) => (
              <View key={i} style={s.poz}>
                <View style={{ flex: 1 }}>
                  <Text style={s.pozNazwa} numberOfLines={1}>{p.walor}</Text>
                  <Text style={s.pozPod}>
                    {p.ilosc} szt.{p.cena ? ` × ${p.cena} ${p.waluta || ""}` : ""}
                    {p.data ? ` · ${p.data}` : ""}
                  </Text>
                </View>
                <Text style={[s.pozTyp, p.kierunek === "sprzedaz" && { color: C.red }]}>
                  {p.kierunek === "sprzedaz" ? "sprzedaż" : "kupno"}
                </Text>
              </View>
            ))}
          </ScrollView>

          <Text style={s.stopka}>
            Odczytane przez {wynik.model.split("/").pop()} ·{" "}
            {wynik.trudnosc?.opis}
            {wynik.obciete ? " · plik był długi i został przycięty" : ""}
          </Text>
          <View style={{ marginTop: 14 }}>
            <MetalButton label="Zamknij podgląd" onPress={() => { gotowe(); zamknij(); }} />
          </View>
        </>
      )}

      {stan === "blad" && (
        <>
          <View style={s.uwaga}>
            <Text style={s.uwagaTxt}>{blad}</Text>
          </View>
          <Text style={s.info}>
            Nieudana próba nie zużywa Twojego darmowego odczytu — możesz
            spróbować jeszcze raz.
          </Text>
          <View style={{ marginTop: 14 }}>
            <MetalButton label="Spróbuj ponownie" onPress={() => setStan("wybor")} tone="green" />
          </View>
        </>
      )}
    </Okno>
  );
}

/* =========================================================== wspólne */

function Okno({ widoczne, zamknij, tytul, podtytul, children }: {
  widoczne: boolean; zamknij: () => void; tytul: string; podtytul: string;
  children: React.ReactNode;
}) {
  return (
    <Modal visible={widoczne} animationType="slide" transparent onRequestClose={zamknij}>
      <View style={s.tlo}>
        <View style={s.okno}>
          <View style={s.glowa}>
            <View style={{ flex: 1 }}>
              <Text style={s.tytul}>{tytul}</Text>
              <Text style={s.podtytul}>{podtytul}</Text>
            </View>
            <Pressable onPress={zamknij} hitSlop={10} style={s.x}>
              <Icon name="zamknij" size={15} color={C.muted} />
            </Pressable>
          </View>
          <ScrollView contentContainerStyle={s.tresc} keyboardShouldPersistTaps="handled">
            {children}
          </ScrollView>
        </View>
      </View>
    </Modal>
  );
}

function Pole({ etykieta, wartosc, zmien, placeholder, numer, sufiks }: {
  etykieta: string; wartosc: string; zmien: (v: string) => void;
  placeholder?: string; numer?: boolean; sufiks?: string;
}) {
  return (
    <View style={{ marginTop: 12 }}>
      <Text style={s.etykieta}>{etykieta}</Text>
      <View style={s.poleWrap}>
        <TextInput value={wartosc} onChangeText={zmien} placeholder={placeholder}
                   placeholderTextColor={C.dim} style={s.pole}
                   keyboardType={numer ? "numeric" : "default"} autoCorrect={false} />
        {!!sufiks && <Text style={s.poleSufiks}>{sufiks}</Text>}
      </View>
    </View>
  );
}

