/** Obserwowane spółki — wyszukiwarka światowych rynków i lista śledzonych walorów.
 *
 *  Wyszukiwanie jest opóźnione (debounce), żeby nie wysyłać zapytania po każdej literze,
 *  a wyniki pokazują od razu, czy walor jest już obserwowany.
 */
import React, { useEffect, useRef, useState } from "react";
import { ActivityIndicator, StyleSheet, Text, TextInput, View } from "react-native";
import { SearchHit, searchMarket, WatchItem, watchAdd, watchRemove } from "../api";
import Logo from "../components/Logo";
import { C, fmtCur, fmtPct, plColor, T } from "../theme";
import { Card, FadeIn, MetalButton, Press, Segmented } from "../ui";
import Icon from "../ui/Icon";

const SORTS = [
  { id: "change", label: "zmiana" },
  { id: "name", label: "nazwa" },
  { id: "added", label: "dodane" },
];

const TYP: Record<string, string> = {
  EQUITY: "akcje", ETF: "ETF", CRYPTOCURRENCY: "krypto",
  INDEX: "indeks", MUTUALFUND: "fundusz",
};

export default function Watchlist({
  items, loading, onChanged, onOpen,
}: {
  items: WatchItem[];
  loading: boolean;
  onChanged: () => void;
  onOpen: (symbol: string) => void;
}) {
  const [q, setQ] = useState("");
  const [hits, setHits] = useState<SearchHit[] | null>(null);
  const [busy, setBusy] = useState(false);
  const [sort, setSort] = useState("change");
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (timer.current) clearTimeout(timer.current);
    const term = q.trim();
    if (term.length < 2) { setHits(null); setBusy(false); return; }
    setBusy(true);
    timer.current = setTimeout(async () => {
      try { setHits(await searchMarket(term)); }
      catch { setHits([]); } finally { setBusy(false); }
    }, 350);
    return () => { if (timer.current) clearTimeout(timer.current); };
  }, [q]);

  async function toggle(symbol: string, watched: boolean, hit?: SearchHit) {
    // odpowiedź serwera i tak odświeży listę — najpierw ruszamy UI, żeby serce
    // reagowało natychmiast
    if (hits) {
      setHits(hits.map((h) => (h.symbol === symbol ? { ...h, watched: !watched } : h)));
    }
    try {
      if (watched) await watchRemove(symbol);
      else await watchAdd(hit ? { symbol, name: hit.name, type: hit.type,
                                  exchange: hit.exchange } : { symbol });
      onChanged();
    } catch { /* przy błędzie kolejne odświeżenie pokaże stan z serwera */ }
  }

  const sorted = [...items].sort((a, b) =>
    sort === "name" ? a.symbol.localeCompare(b.symbol)
      : sort === "added" ? (b.added_at || "").localeCompare(a.added_at || "")
      : (b.change_pct ?? -999) - (a.change_pct ?? -999));

  return (
    <>
      <View style={s.searchWrap}>
        <Text style={s.searchIcon}>⌕</Text>
        <TextInput
          style={s.search}
          value={q}
          onChangeText={setQ}
          placeholder="Szukaj spółki, ETF-u, krypto…"
          placeholderTextColor={C.dim}
          autoCorrect={false}
          autoCapitalize="characters"
          returnKeyType="search"
        />
        {(busy || !!q) && (
          <Press onPress={() => { setQ(""); setHits(null); }} style={s.clear} scaleTo={0.9}>
            {busy ? <ActivityIndicator color={C.muted} size="small" />
                  : <Icon name="zamknij" size={13} color={C.muted} />}
          </Press>
        )}
      </View>

      {hits !== null ? (
        hits.length === 0 && !busy ? (
          <Text style={s.empty}>Nic nie znaleziono. Spróbuj nazwy albo symbolu (np. MSFT).</Text>
        ) : (
          hits.map((h, i) => (
            <FadeIn key={h.symbol} delay={Math.min(i * 18, 200)} offset={8}>
              <Press onPress={() => onOpen(h.symbol)} scaleTo={0.985}>
                <Card style={s.row}>
                  <Logo ticker={h.symbol} size={34} />
                  <View style={{ flex: 1, marginLeft: 11 }}>
                    <Text style={s.sym}>{h.symbol}</Text>
                    <Text style={s.name} numberOfLines={1}>{h.name}</Text>
                    <Text style={s.meta} numberOfLines={1}>
                      {[TYP[h.type] || h.type, h.exchange].filter(Boolean).join(" · ")}
                    </Text>
                  </View>
                  <MetalButton size="sm" tone="red" round active={h.watched}
                               style={{ marginLeft: 8 }}
                               onPress={() => toggle(h.symbol, h.watched, h)}>
                    <Icon name={h.watched ? "serceOn" : "serce"} size={15}
                          color={h.watched ? C.red : C.muted} />
                  </MetalButton>
                </Card>
              </Press>
            </FadeIn>
          ))
        )
      ) : loading ? (
        <View style={{ paddingVertical: 30 }}><ActivityIndicator color={C.green} /></View>
      ) : items.length === 0 ? (
        <View style={s.emptyBox}>
          <Icon name="serce" size={34} color={C.dim} />
          <Text style={s.emptyTitle}>Nic jeszcze nie obserwujesz</Text>
          <Text style={s.empty}>
            Wyszukaj spółkę powyżej i dotknij serduszka. Będziesz widzieć jej dzienną
            zmianę i wejdziesz w szczegóły jednym dotknięciem.
          </Text>
        </View>
      ) : (
        <>
          <View style={s.sortRow}>
            <Segmented options={SORTS} value={sort} onChange={setSort} liquid tone="green" />
          </View>
          {sorted.map((w, i) => (
            <FadeIn key={w.symbol} delay={Math.min(i * 20, 240)} offset={9}>
              <Press onPress={() => onOpen(w.symbol)} scaleTo={0.985}>
                <Card style={s.row}>
                  <Logo ticker={w.symbol} size={34} />
                  <View style={{ flex: 1, marginLeft: 11 }}>
                    <Text style={s.sym}>{w.symbol}</Text>
                    <Text style={s.name} numberOfLines={1}>{w.name}</Text>
                    <Text style={s.meta} numberOfLines={1}>
                      {[TYP[w.type] || w.type, w.exchange].filter(Boolean).join(" · ")}
                    </Text>
                  </View>
                  <View style={{ alignItems: "flex-end" }}>
                    <Text style={s.price}>
                      {w.price != null ? fmtCur(w.price, w.currency || "USD",
                                                Math.abs(w.price) < 10 ? 4 : 2) : "—"}
                    </Text>
                    {w.change_pct != null && (
                      <View style={[s.pill, { backgroundColor: w.change_pct >= 0 ? C.greenDim : C.redDim }]}>
                        <Text style={[s.pillTxt, { color: plColor(w.change_pct) }]}>
                          {fmtPct(w.change_pct)}
                        </Text>
                      </View>
                    )}
                  </View>
                </Card>
              </Press>
            </FadeIn>
          ))}
          <Text style={s.hint}>
            Zmiana liczona od zamknięcia poprzedniej sesji. Dotknij spółki, aby zobaczyć
            wykres, wskaźniki i porównanie z branżą.
          </Text>
        </>
      )}
    </>
  );
}

const s = StyleSheet.create({
  searchWrap: {
    flexDirection: "row", alignItems: "center", backgroundColor: C.elev,
    borderColor: C.border, borderWidth: 1, borderRadius: 13, paddingHorizontal: 12,
    marginBottom: 12,
  },
  searchIcon: { color: C.muted, fontSize: 17, marginRight: 8 },
  search: { flex: 1, color: C.text, fontSize: 15, paddingVertical: 12 },
  clear: { padding: 6, width: 30, alignItems: "center" },

  row: { flexDirection: "row", alignItems: "center", padding: 12, marginBottom: 9 },
  sym: { color: C.text, fontSize: 14.5, fontWeight: "800", letterSpacing: -0.2 },
  name: { color: C.muted, fontSize: 12, marginTop: 1 },
  meta: { color: C.dim, fontSize: 10.5, marginTop: 3 },
  price: { color: C.text, fontSize: 14.5, fontWeight: "800", letterSpacing: -0.2 },
  pill: { borderRadius: 7, paddingHorizontal: 7, paddingVertical: 2, marginTop: 5 },
  pillTxt: { fontSize: 11.5, fontWeight: "800" },

  heart: {
    width: 36, height: 36, borderRadius: 18, alignItems: "center", justifyContent: "center",
    borderWidth: 1, borderColor: C.border2, marginLeft: 8,
  },
  heartOn: { borderColor: "rgba(255,92,108,.5)", backgroundColor: C.redDim },
  heartTxt: { color: C.muted, fontSize: 17, lineHeight: 20 },

  sortRow: { marginBottom: 12 },
  empty: { color: C.muted, fontSize: 12.5, lineHeight: 19, textAlign: "center", paddingHorizontal: 10 },
  emptyBox: { alignItems: "center", gap: 10, paddingVertical: 26 },
  emptyTitle: { color: C.text, ...T.h2 },
  hint: { color: C.dim, fontSize: 11, lineHeight: 16, textAlign: "center", marginTop: 6 },
});
