/** Wykresy sekcji Earnings — wszystkie w react-native-svg, wszystkie interaktywne.
 *
 *  Wspólny pomysł: palec wybiera słupek/punkt (`useSelector`), a nad wykresem
 *  pojawia się dymek z dokładnymi liczbami. Bez tego wykres na telefonie jest tylko
 *  ozdobą — ekran jest za wąski, żeby podpisać każdą wartość.
 *
 *  Świadomie nie ma tu biblioteki wykresów: reszta aplikacji (PortfolioChart) też
 *  rysuje po swojemu, a gotowe pakiety regularnie nie nadążają za nowym RN.
 */
import React, { useMemo, useRef, useState } from "react";
import { LayoutChangeEvent, PanResponder, StyleSheet, Text, View } from "react-native";
import Svg, { Circle, G, Line, Path, Rect, Text as SvgText } from "react-native-svg";
import { EarningsQuarter, EconEvent, MarginPoint } from "../../api";
import { C, fmtBig } from "../../theme";

const PAD = { l: 6, r: 6, t: 10, b: 20 };

/** Zamienia dotknięcie w indeks najbliższego punktu i trzyma go w stanie.
 *
 *  Zwrócony `sel` jest ZAWSZE w zakresie bieżącej serii. To nie jest ostrożność na
 *  zapas: gdy wykres dostaje krótszą serię niż poprzednio (np. przełączenie marż
 *  z kwartalnych na roczne przy zaznaczonym ostatnim słupku), stary indeks
 *  wskazywał poza tablicę i odczyt `data[sel].date` wywracał cały render — czyli
 *  dokładnie ten biały ekran, z którego nie dało się już wyjść.
 */
function useSelector(count: number, width: number, onPick?: (i: number) => void) {
  const [rawSel, setSel] = useState<number | null>(null);
  const selRef = useRef<number | null>(null);
  const sel = rawSel == null || rawSel >= count || rawSel < 0 ? null : rawSel;

  const pick = (x: number) => {
    if (count <= 0 || width <= 0) return;
    const step = (width - PAD.l - PAD.r) / count;
    const i = Math.max(0, Math.min(count - 1, Math.floor((x - PAD.l) / step)));
    if (i !== selRef.current) {
      selRef.current = i;
      setSel(i);
      onPick?.(i);
    }
  };

  const pan = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => true,
        onMoveShouldSetPanResponder: () => true,
        onPanResponderGrant: (e) => pick(e.nativeEvent.locationX),
        onPanResponderMove: (e) => pick(e.nativeEvent.locationX),
        onPanResponderRelease: () => {},
      }),
    [count, width],
  );

  return { sel, setSel, pan };
}

const pct = (v: number | null | undefined, digits = 1) =>
  v == null ? "—" : `${v > 0 ? "+" : ""}${v.toFixed(digits).replace(".", ",")}%`;

const money = (v: number | null | undefined, cur = "") =>
  v == null ? "—" : `${v.toFixed(2).replace(".", ",")}${cur ? " " + cur : ""}`;

/** Etykieta kwartału „2026-03-31" → „1Q26". */
export function qLabel(iso: string): string {
  if (!iso) return "";
  const [y, m] = iso.split("-");
  const q = Math.ceil(Number(m) / 3);
  return `${q}Q${y.slice(2)}`;
}

/* ---------------------------------------------------------------- zaskoczenia */

/** Historia publikacji: słupek = zaskoczenie EPS, kropka = reakcja kursu nazajutrz.
 *
 *  Dwie osie na jednym obrazku są zwykle złym pomysłem, ale tutaj pytanie brzmi
 *  dokładnie „czy pobicie prognozy przekłada się na kurs" — a to widać tylko wtedy,
 *  gdy oba szeregi leżą obok siebie w tej samej siatce kwartałów.
 */
export function SurpriseChart({
  data, height = 190,
}: { data: EarningsQuarter[]; height?: number }) {
  const [w, setW] = useState(0);
  const { sel, pan } = useSelector(data.length, w);

  if (!data.length) return null;

  const innerW = Math.max(1, w - PAD.l - PAD.r);
  const innerH = height - PAD.t - PAD.b;
  const step = innerW / data.length;
  const bw = Math.min(38, step * 0.46);

  const surprises = data.map((d) => d.surprise_pct ?? 0);
  const reactions = data.map((d) => d.reaction_pct ?? 0);
  const sMax = Math.max(1, ...surprises.map(Math.abs));
  const rMax = Math.max(1, ...reactions.map(Math.abs));
  const zero = PAD.t + innerH / 2;

  const yS = (v: number) => zero - (v / sMax) * (innerH / 2 - 4);
  const yR = (v: number) => zero - (v / rMax) * (innerH / 2 - 4);

  const path = data
    .map((d, i) => `${i ? "L" : "M"}${PAD.l + step * (i + 0.5)},${yR(d.reaction_pct ?? 0)}`)
    .join(" ");

  const cur = sel != null ? data[sel] : null;

  return (
    <View onLayout={(e: LayoutChangeEvent) => setW(e.nativeEvent.layout.width)}>
      <View style={s.tipRow}>
        {cur ? (
          <>
            <Text style={s.tipK}>{qLabel(cur.quarter) || cur.quarter}</Text>
            <Text style={[s.tipV, { color: (cur.surprise_pct ?? 0) >= 0 ? C.green : C.red }]}>
              zaskoczenie {pct(cur.surprise_pct)}
            </Text>
            <Text style={[s.tipV, { color: (cur.reaction_pct ?? 0) >= 0 ? C.green : C.red }]}>
              kurs {pct(cur.reaction_pct)}
            </Text>
          </>
        ) : (
          <Text style={s.tipHint}>Dotknij słupka, żeby zobaczyć szczegóły kwartału</Text>
        )}
      </View>

      {w > 0 && (
        <View {...pan.panHandlers}>
          <Svg width={w} height={height}>
            <Line x1={PAD.l} y1={zero} x2={w - PAD.r} y2={zero}
                  stroke="rgba(255,255,255,.14)" strokeWidth={1} />
            {data.map((d, i) => {
              const v = d.surprise_pct ?? 0;
              const y = yS(v);
              const x = PAD.l + step * (i + 0.5) - bw / 2;
              const on = sel === i;
              return (
                <G key={i}>
                  {on && (
                    <Rect x={PAD.l + step * i} y={PAD.t} width={step} height={innerH}
                          fill="rgba(255,255,255,.05)" rx={6} />
                  )}
                  <Rect
                    x={x} y={Math.min(y, zero)} width={bw}
                    height={Math.max(2, Math.abs(zero - y))} rx={3}
                    fill={v >= 0 ? C.green : C.red} opacity={on ? 1 : 0.72}
                  />
                  <SvgText x={PAD.l + step * (i + 0.5)} y={height - 6} fontSize={9}
                           fontWeight="700" fill={on ? C.text : C.dim} textAnchor="middle">
                    {qLabel(d.quarter) || d.period}
                  </SvgText>
                </G>
              );
            })}
            <Path d={path} stroke={C.accent} strokeWidth={2} fill="none"
                  strokeLinejoin="round" strokeLinecap="round" opacity={0.9} />
            {data.map((d, i) => (
              <Circle key={i} cx={PAD.l + step * (i + 0.5)} cy={yR(d.reaction_pct ?? 0)}
                      r={sel === i ? 5 : 3.2} fill={C.accent}
                      stroke={C.bg} strokeWidth={sel === i ? 2 : 0} />
            ))}
          </Svg>
        </View>
      )}

      <View style={s.legend}>
        <Legend color={C.green} label="zaskoczenie EPS (słupki)" />
        <Legend color={C.accent} label="reakcja kursu (linia)" />
      </View>
    </View>
  );
}

/* -------------------------------------------------------------------- marże */

const MARGIN_SERIES = [
  { key: "gross_margin" as const, label: "brutto", color: C.green },
  { key: "operating_margin" as const, label: "operacyjna", color: C.accent },
  { key: "net_margin" as const, label: "netto", color: C.violet },
];

/** Przychód (słupki w tle) i trzy marże (linie) — kwartał po kwartale albo rok po roku. */
export function MarginChart({
  data, height = 210, currency = "",
}: { data: MarginPoint[]; height?: number; currency?: string }) {
  const [w, setW] = useState(0);
  const { sel, pan } = useSelector(data.length, w);

  if (data.length < 2) return null;

  const innerW = Math.max(1, w - PAD.l - PAD.r);
  const innerH = height - PAD.t - PAD.b;
  const step = innerW / data.length;

  const all = data.flatMap((d) => MARGIN_SERIES.map((m) => d[m.key])).filter(
    (v): v is number => typeof v === "number");
  const lo = Math.min(0, ...all);
  const hi = Math.max(1, ...all);
  const span = hi - lo || 1;
  const y = (v: number) => PAD.t + innerH - ((v - lo) / span) * innerH;

  const revMax = Math.max(...data.map((d) => d.revenue || 0), 1);
  const cur = sel != null ? data[sel] : data[data.length - 1];

  return (
    <View onLayout={(e: LayoutChangeEvent) => setW(e.nativeEvent.layout.width)}>
      <View style={s.tipRow}>
        <Text style={s.tipK}>{qLabel(cur.date) || cur.date.slice(0, 4)}</Text>
        <Text style={s.tipV}>{fmtBig(cur.revenue, currency)}</Text>
        {MARGIN_SERIES.map((m) =>
          cur[m.key] == null ? null : (
            <Text key={m.key} style={[s.tipV, { color: m.color }]}>
              {m.label} {(cur[m.key] as number).toFixed(1).replace(".", ",")}%
            </Text>
          ))}
      </View>

      {w > 0 && (
        <View {...pan.panHandlers}>
          <Svg width={w} height={height}>
            {/* przychód jako cień pod liniami — skala własna, bo chodzi o kształt,
                nie o odczyt wartości z osi */}
            {data.map((d, i) => {
              const h = ((d.revenue || 0) / revMax) * innerH * 0.55;
              return (
                <Rect key={i} x={PAD.l + step * i + step * 0.16} y={PAD.t + innerH - h}
                      width={step * 0.68} height={Math.max(1, h)} rx={3}
                      fill="rgba(255,255,255,.06)" />
              );
            })}
            {lo < 0 && (
              <Line x1={PAD.l} y1={y(0)} x2={w - PAD.r} y2={y(0)}
                    stroke="rgba(255,255,255,.18)" strokeWidth={1} strokeDasharray="3 3" />
            )}
            {sel != null && (
              <Line x1={PAD.l + step * (sel + 0.5)} y1={PAD.t}
                    x2={PAD.l + step * (sel + 0.5)} y2={PAD.t + innerH}
                    stroke="rgba(255,255,255,.22)" strokeWidth={1} />
            )}
            {MARGIN_SERIES.map((m) => {
              const pts = data
                .map((d, i) => ({ v: d[m.key], x: PAD.l + step * (i + 0.5) }))
                .filter((p): p is { v: number; x: number } => typeof p.v === "number");
              if (pts.length < 2) return null;
              return (
                <G key={m.key}>
                  <Path
                    d={pts.map((p, i) => `${i ? "L" : "M"}${p.x},${y(p.v)}`).join(" ")}
                    stroke={m.color} strokeWidth={2.2} fill="none"
                    strokeLinejoin="round" strokeLinecap="round"
                  />
                  {pts.map((p, i) => (
                    <Circle key={i} cx={p.x} cy={y(p.v)} r={2.6} fill={m.color} />
                  ))}
                </G>
              );
            })}
            {data.map((d, i) => (
              <SvgText key={i} x={PAD.l + step * (i + 0.5)} y={height - 6} fontSize={9}
                       fontWeight="700" fill={sel === i ? C.text : C.dim} textAnchor="middle">
                {qLabel(d.date) || d.date.slice(0, 4)}
              </SvgText>
            ))}
          </Svg>
        </View>
      )}

      <View style={s.legend}>
        {MARGIN_SERIES.map((m) => <Legend key={m.key} color={m.color} label={`marża ${m.label}`} />)}
        <Legend color="rgba(255,255,255,.22)" label="przychód" />
      </View>
    </View>
  );
}

/* ------------------------------------------------------- historia wskaźnika */

/** Odczyt vs prognoza dla wydarzenia ekonomicznego — ostatnie kilkanaście publikacji. */
export function IndicatorChart({
  data, height = 160,
}: { data: EconEvent[]; height?: number }) {
  const [w, setW] = useState(0);
  const { sel, pan } = useSelector(data.length, w);

  if (data.length < 2) return null;

  const innerW = Math.max(1, w - PAD.l - PAD.r);
  const innerH = height - PAD.t - PAD.b;
  const step = innerW / data.length;

  const vals = data.flatMap((d) => [d.actual, d.consensus]).filter(
    (v): v is number => typeof v === "number");
  const lo = Math.min(...vals);
  const hi = Math.max(...vals);
  const span = hi - lo || 1;
  const y = (v: number) => PAD.t + innerH - ((v - lo) / span) * innerH;

  const cur = sel != null ? data[sel] : data[data.length - 1];
  const line = (key: "actual" | "consensus") =>
    data
      .map((d, i) => ({ v: d[key], x: PAD.l + step * (i + 0.5) }))
      .filter((p): p is { v: number; x: number } => typeof p.v === "number")
      .map((p, i) => `${i ? "L" : "M"}${p.x},${y(p.v)}`)
      .join(" ");

  return (
    <View onLayout={(e: LayoutChangeEvent) => setW(e.nativeEvent.layout.width)}>
      <View style={s.tipRow}>
        <Text style={s.tipK}>{cur.date}</Text>
        {!!cur.actual_fmt && <Text style={[s.tipV, { color: C.green }]}>odczyt {cur.actual_fmt}</Text>}
        {!!cur.consensus_fmt && <Text style={[s.tipV, { color: C.muted }]}>prognoza {cur.consensus_fmt}</Text>}
      </View>

      {w > 0 && (
        <View {...pan.panHandlers}>
          <Svg width={w} height={height}>
            {sel != null && (
              <Line x1={PAD.l + step * (sel + 0.5)} y1={PAD.t}
                    x2={PAD.l + step * (sel + 0.5)} y2={PAD.t + innerH}
                    stroke="rgba(255,255,255,.22)" strokeWidth={1} />
            )}
            <Path d={line("consensus")} stroke={C.dim} strokeWidth={1.8} fill="none"
                  strokeDasharray="4 3" strokeLinejoin="round" />
            <Path d={line("actual")} stroke={C.green} strokeWidth={2.4} fill="none"
                  strokeLinejoin="round" strokeLinecap="round" />
            {data.map((d, i) =>
              d.actual == null ? null : (
                <Circle key={i} cx={PAD.l + step * (i + 0.5)} cy={y(d.actual)}
                        r={sel === i ? 5 : 3} fill={C.green}
                        stroke={C.bg} strokeWidth={sel === i ? 2 : 0} />
              ))}
            {data.map((d, i) =>
              i % Math.ceil(data.length / 5) ? null : (
                <SvgText key={`l${i}`} x={PAD.l + step * (i + 0.5)} y={height - 6} fontSize={9}
                         fontWeight="700" fill={C.dim} textAnchor="middle">
                  {d.date.slice(5)}
                </SvgText>
              ))}
          </Svg>
        </View>
      )}

      <View style={s.legend}>
        <Legend color={C.green} label="odczyt" />
        <Legend color={C.dim} label="prognoza" />
      </View>
    </View>
  );
}

function Legend({ color, label }: { color: string; label: string }) {
  return (
    <View style={s.legendItem}>
      <View style={[s.legendDot, { backgroundColor: color }]} />
      <Text style={s.legendTxt}>{label}</Text>
    </View>
  );
}

const s = StyleSheet.create({
  tipRow: {
    flexDirection: "row", flexWrap: "wrap", alignItems: "center", gap: 10,
    minHeight: 20, marginBottom: 6,
  },
  tipK: { color: C.text, fontSize: 12.5, fontWeight: "800" },
  tipV: { color: C.text, fontSize: 11.5, fontWeight: "700" },
  tipHint: { color: C.dim, fontSize: 11.5, fontWeight: "500" },
  legend: { flexDirection: "row", flexWrap: "wrap", gap: 12, marginTop: 8 },
  legendItem: { flexDirection: "row", alignItems: "center", gap: 5 },
  legendDot: { width: 8, height: 8, borderRadius: 4 },
  legendTxt: { color: C.dim, fontSize: 10.5, fontWeight: "600" },
});

export { money, pct };
