/** Panel dewelopera — sterowanie serwerem i rachunek za AI. Tylko konto właściciela.
 *
 *  Po co osobny ekran, skoro zakładka „Sterowanie" w bocie ma już START/STOP:
 *  tamta jest częścią produktu i mówi językiem użytkownika („próg siły wydźwięku”).
 *  Ta odpowiada na jedno pytanie właściciela — **czy warto, żeby to dziś chodziło** —
 *  więc obok włącznika stoi rachunek, a przy każdym źródle liczba płatnych wywołań,
 *  które wygenerowało. Wyłączenie jednego przełącznika potrafi ściąć większość kosztu.
 *
 *  Panel nie ma własnej zakładki w pasku — rozwija się w „Więcej", żeby nie
 *  zabierać miejsca zakładkom produktu. Widzi go tylko właściciel.
 *
 *  Zabezpieczenie ma dwie warstwy i tylko druga się liczy:
 *  1. sekcja pokazuje się, gdy `/api/me` mówi `owner` — to wygoda, nie ochrona;
 *  2. każdy endpoint pod spodem stoi za `require_owner` i oddaje 403 komukolwiek
 *     innemu. Nawet gdyby ktoś podmienił stan w przeglądarce i rozwinął tę sekcję,
 *     zobaczy komunikat odmowy i żaden przycisk nic nie zrobi.
 */
import React, { useCallback, useEffect, useState } from "react";
import { ActivityIndicator, ScrollView, StyleSheet, Switch, Text, View } from "react-native";
import {
  DevStatus, getDevStatus, setParams, startBot, stopBot,
} from "../api";
import { useAuth } from "../auth/AuthContext";
import { C, T } from "../theme";
import { Card, FadeIn, MetalButton, Press, SectionTitle } from "../ui";
import { SOURCES } from "./bot/sources";

const usd = (v: number) =>
  "$" + v.toLocaleString("pl-PL", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

/** Krótki czas trwania: „3 dni 4 h", „12 min". */
function trwanie(sekundy: number): string {
  if (!sekundy || sekundy < 60) return `${Math.max(0, Math.round(sekundy))} s`;
  const m = Math.floor(sekundy / 60);
  if (m < 60) return `${m} min`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h} h ${m % 60} min`;
  return `${Math.floor(h / 24)} dni ${h % 24} h`;
}

/** Techniczna nazwa źródła z pliku analiz na nazwę z interfejsu. */
const NAZWA_ZRODLA: Record<string, string> = {
  gpw_espi: "GPW — ESPI", sec_edgar: "SEC EDGAR", squawk: "Terminal / X",
  truth_social: "Truth Social", rss: "Departamenty USA", knf: "KNF",
  live_event: "Wystąpienia na żywo", direct: "Bezpośrednie",
};

export default function DevScreen({
  visible, embedded = false,
}: {
  visible?: boolean;
  /** panel rozwinięty wewnątrz „Więcej" — treść bez własnego przewijania,
   *  bo dwa `ScrollView` jeden w drugim gubią gesty i szarpią listą */
  embedded?: boolean;
}) {
  const { me, previewFree, setPreviewFree } = useAuth();
  const [st, setSt] = useState<DevStatus | null>(null);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState("");
  const [potwierdzam, setPotwierdzam] = useState(false);

  const load = useCallback(async () => {
    try { setSt(await getDevStatus()); setErr(""); }
    catch (e: any) { setErr(e?.message || "Nie udało się pobrać stanu serwera"); }
  }, []);

  useEffect(() => { load(); }, [load]);

  // odświeżamy tylko wtedy, gdy zakładka jest na wierzchu — to ekran diagnostyczny,
  // nie ma powodu, żeby odpytywał serwer w tle przez cały czas działania aplikacji
  useEffect(() => {
    if (visible === false) return;
    const t = setInterval(load, 10000);
    return () => clearInterval(t);
  }, [load, visible]);

  async function akcja(nazwa: string, fn: () => Promise<any>) {
    setBusy(nazwa);
    try { await fn(); await load(); }
    catch (e: any) { setErr(e?.message || "Operacja nie powiodła się"); }
    finally { setBusy(""); setPotwierdzam(false); }
  }

  if (err && !st) {
    return (
      <View style={[s.center, embedded && s.centerEmbed]}>
        <Text style={s.errTitle}>{err}</Text>
        <Text style={s.errSub}>
          Ten panel jest dostępny wyłącznie dla konta właściciela. Serwer sprawdza to
          niezależnie od tego, co pokazuje aplikacja.
        </Text>
        <MetalButton label="Spróbuj ponownie" tone="steel" onPress={load} />
      </View>
    );
  }
  if (!st) {
    return (
      <View style={[s.center, embedded && s.centerEmbed]}>
        <ActivityIndicator color={C.violet} size="large" />
      </View>
    );
  }

  const chodzi = st.bot.alive;
  const okno24 = st.koszty.okna.find((o) => o.hours === 24);
  const okno7 = st.koszty.okna.find((o) => o.hours > 24);

  // Ten sam skład treści w dwóch opakowaniach: osobny ekran przewija się sam,
  // rozwinięty w „Więcej" jedzie na przewijaniu tamtego ekranu.
  const Opakowanie: any = embedded ? View : ScrollView;
  const opakowanieProps = embedded
    ? { style: s.embed }
    : { contentContainerStyle: s.wrap, showsVerticalScrollIndicator: false };

  return (
    <Opakowanie {...opakowanieProps}>
      {!embedded && (
        <FadeIn>
          <View style={s.head}>
            <View style={{ flex: 1 }}>
              <Text style={s.h1}>Panel dewelopera</Text>
              <Text style={s.sub}>{me?.user?.email || "konto właściciela"}</Text>
            </View>
            <View style={s.chip}><Text style={s.chipTxt}>TYLKO WŁAŚCICIEL</Text></View>
          </View>
        </FadeIn>
      )}

      {/* ─────────────────────────────── główny włącznik ─────────────────────── */}
      <FadeIn delay={40}>
        <Card style={[s.power, chodzi ? s.powerOn : s.powerOff]}>
          <View style={s.ledRow}>
            <View style={[s.led, { backgroundColor: chodzi ? C.green : C.dim }]} />
            <Text style={[s.ledTxt, { color: chodzi ? C.green : C.muted }]}>
              {chodzi ? "NASŁUCH CHODZI" : "NASŁUCH WYŁĄCZONY"}
            </Text>
            {chodzi && (
              <Text style={s.ledMeta}>
                {trwanie(st.bot.uptime_s)} · {st.bot.cycles.toLocaleString("pl-PL")} cykli
              </Text>
            )}
          </View>

          <Text style={s.powerDesc}>
            {chodzi
              ? "Bot nasłuchuje źródeł i analizuje newsy dla wszystkich użytkowników "
                + "serwera. Każda analiza długiego raportu to zapytanie do płatnego modelu."
              : "Nic nie jest pobierane ani analizowane. Zero kosztów AI, wizytówka bota "
                + "pokazuje gościom „nasłuch zatrzymany”."}
          </Text>

          {chodzi ? (
            <MetalButton
              label={busy === "power" ? "Zatrzymuję…" : "■  ZATRZYMAJ NASŁUCH"}
              tone="red" filled full disabled={Boolean(busy)}
              style={{ marginTop: 14 }}
              onPress={() => akcja("power", stopBot)}
            />
          ) : potwierdzam ? (
            <View style={{ marginTop: 14, gap: 9 }}>
              <Text style={s.confirm}>
                Uruchomienie zacznie naliczać koszty AI
                {st.koszty.prognoza_30d_usd > 0
                  ? ` — przy dotychczasowym ruchu ok. ${usd(st.koszty.prognoza_30d_usd)} / 30 dni.`
                  : "."}
              </Text>
              <View style={{ flexDirection: "row", gap: 9 }}>
                <MetalButton label={busy === "power" ? "Uruchamiam…" : "Tak, uruchom"}
                             tone="green" filled style={{ flex: 1 }} disabled={Boolean(busy)}
                             onPress={() => akcja("power", startBot)} />
                <MetalButton label="Anuluj" tone="steel" style={{ flex: 1 }}
                             onPress={() => setPotwierdzam(false)} />
              </View>
            </View>
          ) : (
            <MetalButton label="▶  URUCHOM NASŁUCH" tone="green" filled full
                         style={{ marginTop: 14 }} disabled={Boolean(busy)}
                         onPress={() => setPotwierdzam(true)} />
          )}

          {st.bot.paused && (
            <Text style={s.warn}>
              Ustawiona jest pauza awaryjna (kill switch) — start ją zdejmie.
            </Text>
          )}
          {!!st.bot.last_error && (
            <Text style={s.err} numberOfLines={3}>Ostatni błąd pętli: {st.bot.last_error}</Text>
          )}
        </Card>
      </FadeIn>

      {/* ─────────────────────────────────── rachunek ────────────────────────── */}
      <SectionTitle hint="Liczone z pliku analiz po stawkach z cennika OpenRoutera. Pre-filtr i modele darmowe nie kosztują nic.">
        Rachunek za AI
      </SectionTitle>

      <FadeIn delay={60}>
        <Card style={s.card}>
          <View style={s.kosztRow}>
            {[okno24, okno7].filter(Boolean).map((o) => (
              <View key={o!.label} style={s.kosztBox}>
                <Text style={s.kosztLabel}>{o!.label}</Text>
                <Text style={s.kosztUsd}>{usd(o!.usd)}</Text>
                <Text style={s.kosztMeta}>
                  {o!.analiz} analiz · {o!.platnych} płatnych · {o!.weryfikacji} weryfikacji
                </Text>
              </View>
            ))}
          </View>

          <View style={s.prognoza}>
            <Text style={s.prognozaLabel}>Prognoza na 30 dni przy dotychczasowym ruchu</Text>
            <Text style={s.prognozaVal}>{usd(st.koszty.prognoza_30d_usd)}</Text>
          </View>

          {/* Zero bez wyjaśnienia czyta się jak „to nic nie kosztuje", a nie jak
              „nie ma z czego liczyć" — a to dwie zupełnie różne informacje. */}
          {!okno7?.analiz && (
            <Text style={s.brakDanych}>
              Brak analiz z ostatnich 7 dni — rachunek wypełni się, gdy bot popracuje.
              Zero nie znaczy tu „za darmo".
            </Text>
          )}

          <Text style={s.note}>
            Stawki: {usd(st.koszty.stawki.analiza)} za analizę płatnym modelem,
            {" "}{usd(st.koszty.stawki.weryfikacja)} za drugą opinię. Koszt nie rośnie
            z liczbą użytkowników — nasłuch jest jeden i wspólny.
          </Text>
        </Card>
      </FadeIn>

      {Object.keys(st.koszty.platne_per_zrodlo).length > 0 && (
        <FadeIn delay={80}>
          <Card style={s.card}>
            <Text style={s.cardTitle}>Skąd biorą się płatne wywołania (7 dni)</Text>
            {Object.entries(st.koszty.platne_per_zrodlo)
              .sort((a, b) => b[1] - a[1])
              .map(([src, n]) => (
                <View key={src} style={s.row}>
                  <Text style={s.rowK}>{NAZWA_ZRODLA[src] || src}</Text>
                  <Text style={s.rowV}>{n} × {usd(st.koszty.stawki.analiza)}</Text>
                </View>
              ))}
            <Text style={s.note}>
              Długie raporty (SEC) zawsze idą przez płatny model — to nie awaria,
              tylko projekt: najpierw streszczenie darmowym, potem analiza płatnym.
              Wyłączenie tego jednego źródła zwykle ścina większość rachunku.
            </Text>
          </Card>
        </FadeIn>
      )}

      {/* ──────────────────────────────────── źródła ─────────────────────────── */}
      <SectionTitle hint="Przełącznik działa od razu, bez restartu bota. Zmiana dotyczy całego serwera.">
        Źródła nasłuchu
      </SectionTitle>

      {st.sources.map((z, i) => {
        const meta = SOURCES.find((x) => x.poll === z.key);
        const platnych = st.koszty.platne_per_zrodlo[zrodloWPliku(z.key)] || 0;
        return (
          <FadeIn key={z.key} delay={Math.min(i * 25, 200)} offset={8}>
            <Card style={s.srcCard}>
              <View style={s.srcRow}>
                <View style={[s.badge, {
                  backgroundColor: (meta?.color || C.dim) + "22",
                  borderColor: (meta?.color || C.dim) + "55",
                }]}>
                  <Text style={[s.badgeTxt, { color: meta?.color || C.dim }]}>
                    {meta?.badge || "?"}
                  </Text>
                </View>
                <View style={{ flex: 1, marginLeft: 10 }}>
                  <Text style={s.srcName}>{meta?.name || z.key}</Text>
                  <Text style={s.srcMeta}>
                    {z.interval ? `co ${z.interval} s` : "—"}
                    {platnych ? `  ·  ${platnych} płatnych / 7 dni` : "  ·  bez kosztu"}
                  </Text>
                </View>
                <Switch
                  value={z.enabled}
                  disabled={Boolean(busy)}
                  onValueChange={(v) => akcja("src", () => setParams({ [z.param]: v }))}
                  trackColor={{ false: "#2a3247", true: "rgba(167,139,250,.5)" }}
                  thumbColor={z.enabled ? C.violet : "#fff"}
                />
              </View>
            </Card>
          </FadeIn>
        );
      })}

      {/* ─────────────────────────────── narzędzia dev ───────────────────────── */}
      <SectionTitle>Narzędzia</SectionTitle>

      <FadeIn delay={60}>
        <Card style={s.card}>
          <View style={s.rowBetween}>
            <View style={{ flex: 1, paddingRight: 12 }}>
              <Text style={s.cardTitle}>Widok bez premium</Text>
              <Text style={s.cardDesc}>
                Pokazuje aplikację tak, jak widzi ją ktoś bez wykupionego dostępu —
                razem z wizytówką bota zamiast zakładek.
              </Text>
            </View>
            <Switch
              value={previewFree}
              onValueChange={setPreviewFree}
              trackColor={{ false: "#2a3247", true: "rgba(167,139,250,.5)" }}
              thumbColor={previewFree ? C.violet : "#fff"}
            />
          </View>
        </Card>
      </FadeIn>

      {/* ───────────────────────────────── diagnostyka ───────────────────────── */}
      <SectionTitle>Diagnostyka</SectionTitle>
      <FadeIn delay={60}>
        <Card style={s.card}>
          <Diag k="Wersja API panelu" v={String(st.panel.api)} />
          <Diag k="Panel działa od" v={trwanie(st.panel.uptime_s)} />
          <Diag k="Pętla bota" v={chodzi ? `${trwanie(st.bot.uptime_s)} · ${st.bot.cycles} cykli` : "zatrzymana"} />
          <Diag k="Ostatnie odpytanie" v={st.bot.last_poll
            ? `${Math.round(st.server_time - st.bot.last_poll)} s temu` : "—"} />
          <Diag k="Włączonych źródeł"
                v={`${st.sources.filter((x) => x.enabled).length} / ${st.sources.length}`} />
          <Diag k="Sprawdzeń na dobę" v={st.sources
            .filter((x) => x.enabled && x.interval > 0)
            .reduce((a, x) => a + Math.round(86400 / x.interval), 0)
            .toLocaleString("pl-PL")} />
        </Card>
      </FadeIn>

      {!!err && <Text style={s.errInline}>{err}</Text>}

      <Text style={s.foot}>
        Wszystkie akcje na tym ekranie dotyczą całego serwera i wszystkich użytkowników.
      </Text>
    </Opakowanie>
  );
}

/** Klucz źródła w `polls` („edgar") na klucz w pliku analiz („sec_edgar"). */
function zrodloWPliku(klucz: string): string {
  const mapa: Record<string, string> = {
    edgar: "sec_edgar", gpw: "gpw_espi", truth: "truth_social", gov: "rss",
  };
  return mapa[klucz] || klucz;
}

function Diag({ k, v }: { k: string; v: string }) {
  return (
    <View style={s.row}>
      <Text style={s.rowK}>{k}</Text>
      <Text style={s.rowV}>{v}</Text>
    </View>
  );
}

const s = StyleSheet.create({
  wrap: { padding: 18, paddingTop: 8, paddingBottom: 48 },
  // rozwinięty w „Więcej": marginesy boczne daje już tamten ekran
  embed: { paddingTop: 2 },
  center: { flex: 1, alignItems: "center", justifyContent: "center", padding: 30, gap: 12 },
  // rozwinięty w „Więcej" nie ma czego wypełniać — bez tego zapadłby się do zera
  centerEmbed: { flex: 0, minHeight: 170 },
  errTitle: { color: C.text, ...T.h2, textAlign: "center" },
  errSub: { color: C.muted, fontSize: 12.5, lineHeight: 18, textAlign: "center", marginBottom: 6 },

  head: { flexDirection: "row", alignItems: "center" },
  h1: { color: C.text, ...T.h1 },
  sub: { color: C.muted, ...T.small, marginTop: 3 },
  chip: {
    borderRadius: 999, paddingHorizontal: 10, paddingVertical: 5,
    backgroundColor: "rgba(167,139,250,.14)", borderWidth: 1, borderColor: "rgba(167,139,250,.45)",
  },
  chipTxt: { color: C.violet, fontSize: 9, fontWeight: "800", letterSpacing: 0.8 },

  power: { padding: 16, marginTop: 16, borderWidth: 1 },
  powerOn: { borderColor: "rgba(47,212,138,.4)" },
  powerOff: { borderColor: C.border },
  ledRow: { flexDirection: "row", alignItems: "center", gap: 9 },
  led: { width: 9, height: 9, borderRadius: 5 },
  ledTxt: { fontSize: 11, fontWeight: "800", letterSpacing: 0.8 },
  ledMeta: { marginLeft: "auto", color: C.dim, fontSize: 11 },
  powerDesc: { color: C.muted, fontSize: 12.5, lineHeight: 18.5, marginTop: 11 },
  confirm: { color: C.amber, fontSize: 12.5, lineHeight: 18 },
  warn: { color: C.amber, fontSize: 11.5, marginTop: 10 },
  err: { color: C.red, fontSize: 11.5, lineHeight: 16, marginTop: 10 },
  errInline: { color: C.red, fontSize: 12, marginTop: 14, textAlign: "center" },

  card: { padding: 15, marginBottom: 9 },
  cardTitle: { color: C.text, fontSize: 14, fontWeight: "800" },
  cardDesc: { color: C.dim, fontSize: 11.5, lineHeight: 17, marginTop: 4 },
  rowBetween: { flexDirection: "row", alignItems: "center" },

  kosztRow: { flexDirection: "row", gap: 10 },
  kosztBox: { flex: 1 },
  kosztLabel: { color: C.dim, ...T.micro },
  kosztUsd: { color: C.text, fontSize: 23, fontWeight: "800", letterSpacing: -0.5, marginTop: 4 },
  kosztMeta: { color: C.muted, fontSize: 10.5, lineHeight: 15, marginTop: 4 },
  prognoza: {
    flexDirection: "row", alignItems: "center", marginTop: 15, paddingTop: 13,
    borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: C.border,
  },
  prognozaLabel: { color: C.muted, fontSize: 12, flex: 1, paddingRight: 12 },
  prognozaVal: { color: C.amber, fontSize: 17, fontWeight: "800" },
  brakDanych: { color: C.dim, fontSize: 11.5, lineHeight: 17, marginTop: 11, fontStyle: "italic" },
  note: {
    color: C.dim, fontSize: 11, lineHeight: 16.5, marginTop: 12,
    paddingTop: 10, borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: C.border,
  },

  row: {
    flexDirection: "row", paddingVertical: 8,
    borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: C.border,
  },
  rowK: { color: C.muted, fontSize: 12, flex: 1, paddingRight: 12 },
  rowV: { color: C.text, fontSize: 12, flex: 1, textAlign: "right" },

  srcCard: { padding: 12, marginBottom: 8 },
  srcRow: { flexDirection: "row", alignItems: "center" },
  badge: { borderRadius: 6, borderWidth: 1, paddingHorizontal: 7, paddingVertical: 3 },
  badgeTxt: { fontSize: 9.5, fontWeight: "800", letterSpacing: 0.5 },
  srcName: { color: C.text, fontSize: 13.5, fontWeight: "700" },
  srcMeta: { color: C.dim, fontSize: 11, marginTop: 3 },

  foot: { color: C.dim, fontSize: 11, lineHeight: 16, textAlign: "center", marginTop: 20 },
});
